c5v0rui0ywl	c5v0rui0ywl	{"parentId":"gey1m47820c","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT v.scenario_name, x.\\"口径\\", x.\\"收益率（%）\\" FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '002078.SZ' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN LATERAL (VALUES ('隐含收益率', round((v.implied_irr * 100)::numeric, 2)), ('现金支持口径', round((v.cash_implied_irr * 100)::numeric, 2)), ('要求收益率', round((v.required_return * 100)::numeric, 2))) x(\\"口径\\", \\"收益率（%）\\") ORDER BY v.sort, 2"},"chart":{"option":{"mode":"basic","builder":{"type":"bar","xField":"scenario_name","yField":"收益率（%）","seriesField":"口径"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.irr_scen"},"cardSettings":{"titleDescription":{"title":"三情景：买入后隐含年化收益率 vs 要求收益率（%）"}}}}
8kvco1qq75g	8kvco1qq75g	{"parentId":"gey1m47820c","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT o.obs_date, round((CASE WHEN co.price_fx_metric_id IS NULL THEN o.value ELSE o.value * fx.value END)::numeric, 2) AS \\"股价\\" FROM vi_obs_current o JOIN vi_company_base co ON co.price_metric_id = o.metric_id AND co.code = '002078.SZ' LEFT JOIN LATERAL (SELECT x.value FROM vi_obs_current x WHERE x.metric_id = co.price_fx_metric_id AND x.obs_date <= o.obs_date ORDER BY x.obs_date DESC LIMIT 1) fx ON true ORDER BY o.obs_date"},"chart":{"option":{"mode":"basic","builder":{"type":"line","xField":"obs_date","yField":"股价"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.price"},"cardSettings":{"titleDescription":{"title":"市场：股价（元；境外报价按当日汇率折算）"}}}}
