uy0mosw32ol	uy0mosw32ol	{"parentId":"d7pqv49jcrp","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT coalesce(t.status, '未裁决') AS \\"裁决\\", count(*) AS n FROM vi_thesis_base t JOIN vi_company_base co ON co.id = t.company_id AND co.code = '01698.HK' GROUP BY 1 ORDER BY 2 DESC"},"chart":{"option":{"mode":"basic","builder":{"type":"pie","pieCategory":"裁决","pieValue":"n"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.theses"},"cardSettings":{"titleDescription":{"title":"核心论点：裁决（成立 / 观察 / 存疑 / 证伪）"}}}}
