q96xt7jkqhh	q96xt7jkqhh	{"parentId":"d7pqv49jcrp","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT h.year::text AS year, x.item AS \\"项目\\", x.v AS \\"亿元\\" FROM vi_fin_history_base h JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' CROSS JOIN LATERAL (VALUES ('现金与定期存款', h.cash), ('带息负债', h.interest_debt)) x(item, v) WHERE h.year >= 2019 UNION ALL SELECT d.period, CASE WHEN d.line_item LIKE '现金%' THEN '现金与定期存款' ELSE '带息负债' END, d.value FROM vi_disclosed d JOIN vi_company_base co ON co.id = d.company_id AND co.code = '01698.HK' WHERE d.period = '2026Q2' AND (d.line_item LIKE '现金%' OR d.line_item LIKE '带息负债%') ORDER BY 1, 2"},"chart":{"option":{"mode":"basic","builder":{"type":"bar","xField":"year","yField":"亿元","seriesField":"项目"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.cash"},"cardSettings":{"titleDescription":{"title":"现金与定期存款 vs 带息负债（亿元）"}}}}
