xb14bl91zwr	xb14bl91zwr	{"parentId":"d7pqv49jcrp","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT h.year::text AS year, '历史' AS \\"口径\\", round((hc.payout * 100)::numeric, 1) AS \\"%\\" FROM vi_fin_history_base h JOIN vi_fin_history_calc hc USING (id) JOIN vi_company_base co ON co.id = h.company_id AND co.code = '01698.HK' WHERE h.year >= 2020 AND hc.payout IS NOT NULL UNION ALL SELECT p.year::text, '预测', round((p.payout * 100)::numeric, 1) FROM vi_projection p JOIN vi_company_base co ON co.id = p.company_id AND co.code = '01698.HK' JOIN vi_model_base m ON m.id = p.model_id AND m.status = '当前' WHERE p.is_base ORDER BY 1"},"chart":{"option":{"mode":"basic","builder":{"type":"bar","xField":"year","yField":"%","seriesField":"口径"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.payout"},"cardSettings":{"titleDescription":{"title":"股东回报率（股息＋回购÷归母净利，%）：历史与基准预测"}}}}
