ylguzeiamn9	ylguzeiamn9	{"parentId":"xz4he37qyde","subKey":"items","subType":"array","use":"TableBlockModel","props":{},"decoratorProps":{},"stepParams":{"resourceSettings":{"init":{"dataSourceKey":"main","collectionName":"vi_observation"}},"__flowSurfaceMeta":{"declaredKey":"公司披露.disclosed"},"cardSettings":{"titleDescription":{"description":"每个指标每一期的数值，以及对它的理解（经营影响、经营解读）；引用【来源文档】【指标】【原始采集记录】；被【自动检查】引用。"}},"tableSettings":{"pageSize":{"pageSize":50},"tableDensity":{"size":"middle"},"defaultSorting":{"sort":[{"field":"obs_date","direction":"desc"}]},"dataScope":{"filter":{"logic":"$and","items":[{"path":"metric.company_id","operator":"$eq","value":2},{"path":"metric.source_kind","operator":"$eq","value":"公司披露"}]}}}}}
