db76r867515	db76r867515	{"parentId":"ugr1ridksrl","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT v.scenario_name, x.\\"口径\\", x.\\"收益率（%）\\" FROM vi_valuation v JOIN vi_model_base m ON m.id = v.model_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN LATERAL (VALUES ('隐含收益率', round((v.implied_irr * 100)::numeric, 2)), ('现金支持口径', round((v.cash_implied_irr * 100)::numeric, 2)), ('要求收益率', round((v.required_return * 100)::numeric, 2))) x(\\"口径\\", \\"收益率（%）\\") ORDER BY v.sort, 2"},"chart":{"option":{"mode":"basic","builder":{"type":"bar","xField":"scenario_name","yField":"收益率（%）","seriesField":"口径"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.irr_scen"},"cardSettings":{"titleDescription":{"title":"三情景：买入后隐含年化收益率 vs 要求收益率（%）"}}}}
bz2n5yki9n3	bz2n5yki9n3	{"parentId":"ugr1ridksrl","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT x.price AS \\"买入价\\", '隐含收益率' AS \\"系列\\", round((vi_irr(f.divs, f.taus, f.td, f.ttau, f.cf_g, x.price) * 100)::numeric, 2) AS \\"收益率\\" FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) UNION ALL SELECT x.price, '要求收益率', round((f.required_return * 100)::numeric, 2) FROM vi_valuation_cf f JOIN vi_scenario_base s ON s.id = f.scenario_id AND s.is_base JOIN vi_model_base m ON m.id = f.model_id JOIN vi_company_calc cc ON cc.id = m.company_id JOIN vi_company_base co ON co.id = m.company_id AND co.code = '601668.SH' JOIN vi_model_base m0 ON m0.id = m.id AND m0.status = '当前' CROSS JOIN generate_series(greatest(1, floor(cc.latest_price * 0.5))::int, ceil(cc.latest_price * 1.6)::int) x(price) ORDER BY 1, 2"},"chart":{"option":{"mode":"basic","builder":{"type":"line","xField":"买入价","yField":"收益率","seriesField":"系列"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.irr_curve"},"cardSettings":{"titleDescription":{"title":"买入价 → 隐含年化收益率（基准情景，%）"}}}}
