1uwhb5gslmo	1uwhb5gslmo	{"parentId":"jsgkz08ee0b","subKey":"items","subType":"array","use":"ChartBlockModel","props":{},"decoratorProps":{},"stepParams":{"chartSettings":{"configure":{"query":{"mode":"sql","sql":"SELECT x.m AS \\"倍数\\", s.scenario_name AS \\"系列\\", round(((coalesce(s.core_earnings, 0) * x.m + coalesce(s.mature_earn_pv, 0) * x.m + coalesce(s.mature_interim_pv, 0) + coalesce(s.growth_value, 0) + coalesce(s.invest_value, 0) + coalesce(s.direct_value, 0) + s.noncore) / s.shares)::numeric, 2) AS \\"每股价值\\", s.id FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01810.HK' CROSS JOIN generate_series(4, 24, 2) x(m) UNION ALL SELECT x.m, '市场价', round(s.market_price::numeric, 2), 999 FROM vi_sotp s JOIN vi_company_base co ON co.id = s.company_id AND co.code = '01810.HK' CROSS JOIN generate_series(4, 24, 2) x(m) WHERE s.is_base ORDER BY 1, 4"},"chart":{"option":{"mode":"basic","builder":{"type":"line","xField":"倍数","yField":"每股价值","seriesField":"系列"}}}}},"__flowSurfaceMeta":{"declaredKey":"驾驶舱.sotp_grid"},"cardSettings":{"titleDescription":{"title":"分部加总：倍数 → 每股价值（元；核心业务或成熟业务的倍数）"}}}}
