er-left:1px solid #000000\\">7<!-- 年 -->年</th>\\r\\n\\t\\t\\t\\t    <th style=\\"border-left:1px solid #000000\\">10<!-- 年 -->年</th>\\r\\n\\t\\t\\t\\t    <th style=\\"border-left:1px solid #000000\\">30<!-- 年 -->年</th>\\r\\n\\t\\t\\t\\t</tr>\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\t\\t    <tr>\\r\\n\\t\\t\\t\\t       <td style=\\"width: 250px;text-align: left; line-height: 1\\">中债国债收益率曲线</td>\\r\\n                      <!--  <td style=\\"border-left:1px solid #000000\\">0.9702 </td> -->\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.1802</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.1902</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.2298</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.2659</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4070</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.5054</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.6820</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">2.1260</td>\\r\\n\\t\\t\\t\\t    </tr>\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\t\\t    <tr>\\r\\n\\t\\t\\t\\t       <td style=\\"width: 250px;text-align: left; line-height: 1\\">中债商业银行普通债收益率曲线(AAA)</td>\\r\\n                      <!--  <td style=\\"border-left:1px solid #000000\\">1.3900 </td> -->\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4279</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4552</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4860</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.5529</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.5762</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.7364</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.9213</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">2.3125</td>\\r\\n\\t\\t\\t\\t    </tr>\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\t\\t    <tr>\\r\\n\\t\\t\\t\\t       <td style=\\"width: 250px;text-align: left; line-height: 1\\">中债中短期票据收益率曲线(AAA)</td>\\r\\n                      <!--  <td style=\\"border-left:1px solid #000000\\">1.4600 </td> -->\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4750</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.4872</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.5179</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.6390</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.7122</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">1.8329</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\">2.0194</td>\\r\\n                       <td style=\\"border-left:1px solid #000000\\"></td>\\r\\n\\t\\t\\t\\t    </tr>\\r\\n\\t\\t\\t\\t\\r\\n\\t\\t\\t</table>\\r\\n\\t\\t</div>\\r\\n\\t\\t<div id=\\"zhu\\"> <!-- 注：表中三个月期限国债收益率是用于计算SDR利率的人民币代表性利率 -->注：&nbsp;表中三个月期限国债收益率是用于计算SDR利率的人民币代表性利率</div>\\r\\n\\t\\t<div id=\\"font1\\">\\r\\n\\t\\t\\t\\r\\n\\t\\t\\t\\t<div style=\\"font-weight:bold; text-align: center;\\">\\r\\n\\t\\t               <!-- 国债及其他收益率曲线简介 -->国债及其他债券收益率曲线简介\\r\\n\\t\\t    \\t</div>\\r\\n\\t\\t\\t\\r\\n\\t\\t      <div>\\r\\n\\t\\t         &nbsp; &nbsp; <!-- 国债及其他收益率曲线是由中央国债登记结算有限责任公司(www.chinabond.com.cn)编制提供的一组反映在岸人民币债券市场到期收益率走势的图表。\\r\\n\\t\\t                            其中，国债收益率曲线样本包括记账式附息国债和记账式贴现国债；AAA级商业银行普通债曲线样本包括同业存单和商业银行债券；AAA级中短期票据曲线样本包括AAA级超短期融资券、短期融资券和中期票据 -->\\r\\n\\t\\t                            国债及其他债券收益率曲线是由中央国债登记结算有限责任公司(www.chinabond.com.cn)编制提供的一组反映在岸人民币债券市场到期收益率走势的图表。其中，国债收益率曲线样本包括记账式附息国债和记账式贴现国债；AAA级商业银行普通债收益率曲线样本包括同业存单和商业银行债券；AAA级中短期票据收益率曲线样本包括AAA级超短期融资券、短期融资券和中期票据。\\r\\n\\t\\t      </div>\\r\\n\\t\\t      <div>\\r\\n\\t\\t        &nbsp; &nbsp; <!-- 中债收益率曲线包括国债在内的各信用等级的到期、即期和远期收益曲线约1000余条，采用赫尔米特模型编制。曲线数据源包括银行间市场和交易所市场的做市商报价、\\r\\n\\t\\t                       货币经纪公司报价、成交价和结算价等。收益率曲线的样本点优先选取新发行且满足流动性要求的债券。中债收益率曲线每个工作日日终发布一次，发布时间为北京时间17:30 -->\\r\\n\\t\\t                           中债收益率曲线包括国债在内的各信用等级的到期、即期和远期收益曲线约1000余条，采用赫尔米特模型编制。曲线数据源包括银行间市场和交易所市场的做市商报价、货币经纪公司报价、成交价和结算价等。收益率曲线的样本点优先选取新发行且满足流动性要求的债券。中债收益率曲线每个工作日日终发布一次，发布时间为北京时间17:30。\\r\\n\\t\\t     </div>\\r\\n\\t\\t</div>\\r\\n\\t</div>\\r\\n\\t<input type=\\"hidden\\" id=\\"locale\\" value=\\"cn_ZH\\">\\r\\n</body>\\r\\n\\r\\n<script type=\\"text/javascript\\">\\r\\n\\r\\n    Highcharts.setOptions({\\r\\n        global: {\\r\\n            useUTC: false\\r\\n        },\\r\\n    });\\r\\n    var chart = null;\\r\\n    var xData=new Array();\\r\\n    var options = {\\r\\n        chart : {\\r\\n            exporting : {\\r\\n                enabled : true //用来设置是否显示‘打印’,'导出'等功能按钮，不设置时默认为显示\\r\\n            },\\r\\n            renderTo : 'graph',\\r\\n            type: 'line',\\r\\n            marginBottom : 90,\\r\\n            marginTop : 5,\\r\\n            marginLeft : 50,\\r\\n        },\\r\\n        title : {\\r\\n            text : ''\\r\\n        },\\r\\n        xAxis : {\\r\\n            labels:{\\r\\n                style:{\\r\\n                    fontSize:'10px',\\r\\n                    fontFamily: \\"宋体\\",\\r\\n                    color: \\"#333333\\",\\r\\n                }\\r\\n            },\\r\\n            crosshair: {\\r\\n                width: 1,\\r\\n                color: '#CC0000'\\r\\n            },\\r\\n            categories:xData,\\r\\n            tickPositions: [0,10, 20,30, 50,70,110],\\r\\n            tickWidth : 1,\\r\\n            gridLineWidth : 1,\\r\\n            lineWidth : 1,\\r\\n            lineColor : 'black',\\r\\n            showFirstLabel : true,\\r\\n            showLastLable : true,\\r\\n            tickLength : 0