r z = \\"-\\";\\r\\n\\t\\t\\t\\t\\tvar q = \\"-\\";\\r\\n\\t\\t\\t\\t\\tvar oq = \\"-\\";\\r\\n\\t\\t\\t\\t\\tvar wptnColor = \\"\\";\\r\\n\\t\\t\\t\\t\\tif(sssqTmp.z) {\\r\\n\\t\\t\\t\\t\\t\\tz = (sssqTmp.z * 1).toFixed(2);\\r\\n\\t\\t\\t\\t\\t}\\r\\n\\t\\t\\t\\t\\tif(sssqTmp.q > 0) {\\r\\n\\t\\t\\t\\t\\t\\tq = (sssqTmp.q * 1).toFixed(0);\\r\\n\\t\\t\\t\\t\\t}\\r\\n\\t\\t\\t\\t\\tif(sssqTmp.oq > 0) {\\r\\n\\t\\t\\t\\t\\t\\toq = (sssqTmp.oq * 1).toFixed(0);\\r\\n\\t\\t\\t\\t\\t}\\r\\n\\t\\t\\t\\t\\tif(sssqTmp.wptn == 4) {\\r\\n\\t\\t\\t\\t\\t\\t// 落\\r\\n\\t\\t\\t\\t\\t\\twptnColor = '#009900';\\r\\n\\t\\t\\t\\t\\t} else if(sssqTmp.wptn == 5) {\\r\\n\\t\\t\\t\\t\\t\\t// 涨\\r\\n\\t\\t\\t\\t\\t\\twptnColor = '#ff0000';\\r\\n\\t\\t\\t\\t\\t}\\r\\n\\t\\t\\t\\t\\tvar ioqTd = '<td class=\\"'+trClass+'\\">' + q + '</td>';\\r\\n\\t\\t\\t\\t\\tif(oq != '-') {\\r\\n\\t\\t\\t\\t\\t\\tioqTd = '<td class=\\"'+trClass+'\\">' + q + '(入)<br/>' + oq + '(出)' + '</td>';\\r\\n\\t\\t\\t\\t\\t}\\r\\n\\t\\t\\t\\t\\t\\r\\n\\t\\t\\t\\t\\tsqHtml += '<tr><td class=\\"'+trClass+'\\"><a href=\\"#'+sssqTmp.stcd+'\\" >' + sssqTmp.stnm + '</a></td><td class=\\"'+trClass+'\\">' + getTime(sssqTmp.tm) + '</td><td class=\\"'+trClass+'\\"><font color=\\"' + wptnColor + '\\">' + z + '</font></td>' + ioqTd + '</tr>';\\r\\n\\r\\n//sqHtml += '<tr><td class=\\"'+trClass+'\\"><a href=\\"#\\" >' + sssqTmp.stnm + '</a></td><td class=\\"'+trClass+'\\">' + sssqTmp.tm + '</td><td class=\\"'+trClass+'\\"><font color=\\"' + wptnColor + '\\">' + z + '</font></td>' + ioqTd + '</tr>';\\r\\n\\t\\t\\t\\t}\\r\\n$(\\"#sssqold\\").html(sqHtml);\\r\\n\\t\\t\\t}\\r\\n\\r\\n\\t\\t\\tfunction getTime(ntime) {\\r\\nif(ntime=='-'){return '-';}\\r\\n\\t\\t\\t\\tvar now = new Date(ntime);\\r\\n\\t\\t\\t\\tvar year = now.getYear();\\r\\n\\t\\t\\t\\tvar month = now.getMonth() + 1;\\r\\n\\t\\t\\t\\tvar date = now.getDate();\\r\\n\\t\\t\\t\\tvar hour = now.getHours();\\r\\n\\t\\t\\t\\tvar minute = now.getMinutes();\\r\\n\\t\\t\\t\\tvar second = now.getSeconds();\\r\\n\\t\\t\\t\\treturn PrefixInteger(date, 2) + \\"日 \\" + PrefixInteger(hour, 2) + \\"时\\"+PrefixInteger(minute, 2) + \\"分\\";;\\r\\n\\r\\n\\t\\t\\t}\\r\\n\\t\\t\\tfunction PrefixInteger(num, n) {\\r\\n\\t\\t\\t\\treturn(Array(n).join(0) + num).slice(-n);\\r\\n\\t\\t\\t}\\r\\n\\r\\nwindow.addEventListener('message',function(rs){\\r\\n    var pointdata=rs.data;\\r\\nif(pointdata=='refresh'){\\r\\n     window.location.reload();\\r\\n}else{\\r\\nconsole.log(pointdata);\\r\\n}\\r\\n})\\r\\n</script>\\r\\n\\t</body>\\r\\n\\r\\n</html>\\r\\n","headers":{"Server":"nginx","Set-Cookie":"WJSESSIONID=E4FAB41B5A8076F85ED64C6C4FCD2E6D; Path=/; HttpOnly","X-Bd-Remote-Connection-Info":"lf-lf02-bgp; bind=123.58.10.239; local=123.58.10.239:31360; remote=219.140.196.72:80","X-Bd-Upstream-Id":"lf-lf02-bgp","Connection":"Keep-Alive","Content-Type":"text/html;charset=utf-8","Date":"Tue, 29 Sep 2026 10:30:17 GMT"},"status_code":200,"$startTime":1790677808017,"$endTime":1790677809351}	3	2026-10-21 21:23:27.860014+08	2026-10-21 21:23:27.860014+08	\N	\N
