--
-- Name: SCHEMA archive_feishu; Type: COMMENT; Schema: -; Owner: nocobase
--

COMMENT ON SCHEMA archive_feishu IS '飞书迁移结构（cj_）的只读归档：2026-10-21 重构为 vi_ 框架前的全部输入数据';


--
-- Name: vi_biz_model_dml(); Type: FUNCTION; Schema: public; Owner: nocobase
--

CREATE FUNCTION public.vi_biz_model_dml() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE vi_biz_model_base SET code = NEW.code, element = NEW.element, title = NEW.title, content = NEW.content, metric = NEW.metric, trend = NEW.trend, company_id = NEW.company_id WHERE id = OLD.id;
