-- Name: vi_pct(double precision, integer); Type: FUNCTION; Schema: public; Owner: nocobase
--

CREATE FUNCTION public.vi_pct(x double precision, digits integer DEFAULT 1) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN x IS NULL THEN '—' ELSE round((x * 100)::numeric, digits)::text || '%' END
$$;


