    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    RETURN NEW;
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE vi_period_data_base SET period = NEW.period, period_end = NEW.period_end, period_kind = NEW.period_kind, line_item = NEW.line_item, value = NEW.value, unit = NEW.unit, yoy = NEW.yoy, impact = COALESCE(NEW.impact, '待判断'), assessment = NEW.assessment, summary = NEW.summary, status = NEW.status, company_id = NEW.company_id, source_id = NEW.source_id WHERE id = OLD.id;
    RETURN NEW;
  ELSE
    DELETE FROM vi_period_data_base WHERE id = OLD.id;
    RETURN OLD;
  END IF;
END $$;


ALTER FUNCTION public.vi_period_data_dml() OWNER TO nocobase;

--
-- Name: vi_put_disclosed(bigint, text, text, text, text, date, double precision, double precision, text, text, text, text, bigint); Type: FUNCTION; Schema: public; Owner: nocobase
--

CREATE FUNCTION public.vi_put_disclosed(p_company bigint, p_item text, p_basis text, p_unit text, p_period text, p_end date, p_value double precision, p_yoy double precision, p_impact text, p_assessment text, p_summary text, p_status text, p_doc bigint) RETURNS bigint
    LANGUAGE plpgsql
    AS $_$
DECLARE mid bigint; ccode text; n int; oid bigint;
BEGIN
  SELECT id INTO mid FROM vi_metric_base
   WHERE company_id = p_company AND source_kind = '公司披露' AND name = p_item AND basis IS NOT DISTINCT FROM p_basis
     AND unit IS NOT DISTINCT FROM p_unit
   ORDER BY id LIMIT 1;
  IF mid IS NULL THEN
    SELECT code INTO ccode FROM vi_company_base WHERE id = p_company;
    SELECT coalesce(max(substring(code FROM '\.D(\d+)$')::int), 0) + 1 INTO n FROM vi_metric_base WHERE code LIKE ccode || '.D%';
    VALUES (ccode || '.D' || lpad(n::text, 3, '0'), p_item, p_unit, '经营', '公司披露', p_basis, p_company, '公司披露',
            CASE p_basis WHEN '单季' THEN '季' WHEN '半年累计' THEN '半年' WHEN '前三季度累计' THEN '年' WHEN '全年' THEN '年' END)
    RETURNING id INTO mid;
  END IF;
  DELETE FROM vi_observation_base WHERE metric_id = mid AND period IS NOT DISTINCT FROM p_period;
  VALUES (mid, p_end, p_period, p_value, p_yoy, p_impact, p_assessment, p_summary, p_status, p_doc, now())
  RETURNING id INTO oid;
  RETURN oid;
END $_$;


ALTER FUNCTION public.vi_put_disclosed(p_company bigint, p_item text, p_basis text, p_unit text, p_period text, p_end date, p_value double precision, p_yoy double precision, p_impact text, p_assessment text, p_summary text, p_status text, p_doc bigint) OWNER TO nocobase;

--
-- Name: vi_pv(double precision[], double precision[], double precision, double precision, double precision, double precision); Type: FUNCTION; Schema: public; Owner: nocobase
--

CREATE FUNCTION public.vi_pv(divs double precision[], taus double precision[], td double precision, ttau double precision, g double precision, r double precision) RETURNS double precision
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE WHEN r IS NULL OR g IS NULL OR td IS NULL OR r <= g OR r <= -1 THEN NULL ELSE
    coalesce((SELECT sum(d / power(1 + r, tau)) FROM unnest(divs, taus) AS x(d, tau) WHERE tau > 0), 0)
    + td * (1 + g) / (r - g) / power(1 + r, ttau) END
$$;


ALTER FUNCTION public.vi_pv(divs double precision[], taus double precision[], td double precision, ttau double precision, g double precision, r double precision) OWNER TO nocobase;

