--
-- Name: vi_forecast_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_forecast_calc AS
 WITH d AS (
         SELECT f.id,
            f.year,
            f.volume,
            f.price,
            f.cash_cost,
            f.depreciation,
            f.other_contrib,
            f.tax_rate,
            f.minority_share,
            f.payout,
            f.net_borrowing,
            f.cost_of_debt,
            f.noncash_gain_deduct,
            f.investee_cash_div,
            f.other_cash_adj,
            f.wc_increase,
            f.maint_capex,
            f.growth_capex,
            f.min_cash_topup,
            f.operating_status,
            f.cash_status,
            f.note,
            f.model_id,
            f.created_at,
            f.updated_at,
            m.opening_debt,
            sum(f.net_borrowing) OVER w AS nb_before,
            count(*) OVER w AS n_before,
            count(f.net_borrowing) OVER w AS nb_known_before
           FROM (public.vi_forecast_base f
             LEFT JOIN public.vi_model_base m ON ((m.id = f.model_id)))
          WINDOW w AS (PARTITION BY f.model_id ORDER BY f.year ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING)
        ), e AS (
         SELECT d.id,
            d.year,
            d.volume,
            d.price,
            d.cash_cost,
            d.depreciation,
            d.other_contrib,
            d.tax_rate,
            d.minority_share,
            d.payout,
            d.net_borrowing,
            d.cost_of_debt,
            d.noncash_gain_deduct,
            d.investee_cash_div,
            d.other_cash_adj,
            d.wc_increase,
            d.maint_capex,
            d.growth_capex,
            d.min_cash_topup,
            d.operating_status,
            d.cash_status,
            d.note,
            d.model_id,
            d.created_at,
            d.updated_at,
            d.opening_debt,
            d.nb_before,
            d.n_before,
            d.nb_known_before,
                CASE
                    WHEN (COALESCE(d.n_before, (0)::bigint) = COALESCE(d.nb_known_before, (0)::bigint)) THEN (d.opening_debt + COALESCE(d.nb_before, (0)::double precision))
                    ELSE NULL::double precision
                END AS debt_open_
           FROM d
        )
 SELECT id,
    (volume * price) AS revenue,
    debt_open_ AS debt_open,
    (debt_open_ + net_borrowing) AS debt_close,
    (((debt_open_ + (debt_open_ + net_borrowing)) / (2)::double precision) * cost_of_debt) AS interest,
    (depreciation * ((1)::double precision - minority_share)) AS attrib_da,
    ((noncash_gain_deduct IS NOT NULL) AND (investee_cash_div IS NOT NULL) AND (other_cash_adj IS NOT NULL) AND (wc_increase IS NOT NULL) AND (maint_capex IS NOT NULL) AND (growth_capex IS NOT NULL) AND (min_cash_topup IS NOT NULL) AND (net_borrowing IS NOT NULL)) AS cash_complete
   FROM e;


ALTER VIEW public.vi_forecast_calc OWNER TO nocobase;

