-- Name: TABLE vi_metric_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_metric_base IS '指标：每条数字序列的定义：自动采集的行情、利率、水文，以及公司定期披露的经营数字；被【公司】【事实摘录】【数据】【估值模型】【跟踪事项】【采集配置】【自动检查】引用。一条数字序列的定义，数值在「数据」里。来源方式区分自动采集、公司披露、年报和手工整理；所属公司为空的是宏观数据（利率、汇率、商品等），归“宏观数据”项目所有，各公司按需使用；只和一家公司有关的（股价、水位、发电量、销量）挂在这家公司下。同一含义不同口径（单季、累计）分成不同指标，不拼接。';


--
-- Name: COLUMN vi_metric_base.code; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.code IS '指标代码：稳定的英文代码，如 600900.SH.PRICE';


--
-- Name: COLUMN vi_metric_base.name; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.name IS '指标名称';


--
-- Name: COLUMN vi_metric_base.unit; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.unit IS '单位：利率类直接存百分数值，如 1.65 表示 1.65%';


--
-- Name: COLUMN vi_metric_base.category; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.category IS '类别（可选：行情、利率、汇率、商品、宏观、水文、经营、其他）';


--
-- Name: COLUMN vi_metric_base.source_name; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.source_name IS '数据来源';


--
-- Name: COLUMN vi_metric_base.frequency; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.frequency IS '频率';


--
-- Name: COLUMN vi_metric_base.valid_min; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.valid_min IS '合理下限：超出范围的观察标记为无效，不参与计算';


--
-- Name: COLUMN vi_metric_base.valid_max; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.valid_max IS '合理上限';


--
-- Name: COLUMN vi_metric_base.notes; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.notes IS '说明';


--
-- Name: COLUMN vi_metric_base.company_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.company_id IS '所属公司（关联 公司）';


--
-- Name: COLUMN vi_metric_base.source_kind; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.source_kind IS '来源方式：数据页按它分标签：公司披露的在“公司披露”，其余在“自动采集”（可选：自动采集、公司披露、年报、手工整理）';


--
-- Name: COLUMN vi_metric_base.basis; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_metric_base.basis IS '口径：时点＝某一天的值（股价、利率、水位）；其余为期间数（可选：时点、单季、半年累计、前三季度累计、全年）';


--
-- Name: vi_observation_base; Type: TABLE; Schema: public; Owner: nocobase
--

CREATE TABLE public.vi_observation_base (
    id bigint NOT NULL,
    obs_date date,
    value double precision,
    collected_at timestamp with time zone,
    source text,
    note text,
    metric_id bigint,
    raw_capture_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    period text,
    yoy double precision,
    impact text,
    assessment text,
    summary text,
    status text,
    doc_id bigint
);


ALTER TABLE public.vi_observation_base OWNER TO nocobase;

--
-- Name: TABLE vi_observation_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_observation_base IS '数据：每个指标每一期的数值，以及对它的理解（经营影响、经营解读）；引用【来源文档】【指标】【原始采集记录】；被【自动检查】引用。一行＝某个指标在某一期的一个数：自动采集的按天（股价、利率、水位），公司披露的按期（发电量、销量、新签合同额）。同一指标同一日期多次采集时取最后一次为“当前版本”；超出合理范围的为无效。公司披露的数据写期间、同比、来源文档，以及经营影响、经营解读和披露摘要。';


--
-- Name: COLUMN vi_observation_base.obs_date; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.obs_date IS '观察日期：自动采集为采集到的日期；公司披露为期末日期';


--
-- Name: COLUMN vi_observation_base.value; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.value IS '数值';


--
-- Name: COLUMN vi_observation_base.collected_at; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.collected_at IS '采集时间';


--
-- Name: COLUMN vi_observation_base.source; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.source IS '采集地址';


--
-- Name: COLUMN vi_observation_base.note; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.note IS '使用边界';


--
-- Name: COLUMN vi_observation_base.metric_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.metric_id IS '指标（关联 指标）';


--
-- Name: COLUMN vi_observation_base.raw_capture_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.raw_capture_id IS '原始采集记录（关联 原始采集记录）';


--
-- Name: COLUMN vi_observation_base.period; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.period IS '期间：公司披露的数据填，如 2026Q3、2026H1、2025';


--
-- Name: COLUMN vi_observation_base.yoy; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.yoy IS '同比（小数，0.05＝5%）';


--
-- Name: COLUMN vi_observation_base.impact; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.impact IS '经营影响：结合比较基准与经营解读，判断这项数据对公司经营的影响。中性表示已有依据支持影响有限；待判断表示依据不足。（可选：利好、中性、利空、待判断）';


--
-- Name: COLUMN vi_observation_base.assessment; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.assessment IS '经营解读：结合公司业务说明比较基准、变化原因及对利润或模型假设的影响；缺少依据时留空。';


--
-- Name: COLUMN vi_observation_base.summary; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.summary IS '披露摘要与口径：记录披露事实、统计范围、单季或累计口径、管理层披露摘要与推算过程；研究判断写在经营解读。';


--
-- Name: COLUMN vi_observation_base.status; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.status IS '处理状态（可选：已入模、待处理、无需入模）';


--
-- Name: COLUMN vi_observation_base.doc_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_observation_base.doc_id IS '来源文档（关联 来源文档）';


--
-- Name: vi_observation_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_observation_calc AS
 SELECT o.id,
    m.unit,
    m.basis,
    m.source_kind,
    (o.id = ( SELECT o2.id
           FROM public.vi_observation_base o2
          WHERE ((o2.metric_id = o.metric_id) AND (o2.obs_date = o.obs_date))
          ORDER BY o2.collected_at DESC NULLS LAST, o2.id DESC
         LIMIT 1)) AS is_current,
    ((o.value IS NOT NULL) AND (o.value >= COALESCE(m.valid_min, '-Infinity'::double precision)) AND (o.value <= COALESCE(m.valid_max, 'Infinity'::double precision))) AS is_valid
   FROM (public.vi_observation_base o
     LEFT JOIN public.vi_metric_base m ON ((m.id = o.metric_id)));


ALTER VIEW public.vi_observation_calc OWNER TO nocobase;

--
-- Name: vi_obs_current; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_obs_current AS
 SELECT o.metric_id,
    o.obs_date,
    o.value,
    o.id
   FROM (public.vi_observation_base o
     JOIN public.vi_observation_calc c USING (id))
  WHERE (c.is_current AND c.is_valid);


ALTER VIEW public.vi_obs_current OWNER TO nocobase;

--
-- Name: vi_model_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_model_calc AS
 SELECT m.id,
    (round(((m.rf + m.erp))::numeric, 3))::double precision AS base_discount_rate,
    public.vi_today() AS valuation_date,
    (((public.vi_today() - make_date(m.base_year, 12, 31)))::numeric / 365.25) AS years_elapsed,
    l.value AS latest_rf,
    l.obs_date AS latest_rf_date
   FROM (public.vi_model_base m
     LEFT JOIN LATERAL ( SELECT x.value,
            x.obs_date
           FROM public.vi_obs_current x
          WHERE (x.metric_id = m.rf_metric_id)
          ORDER BY x.obs_date DESC
         LIMIT 1) l ON (true));


ALTER VIEW public.vi_model_calc OWNER TO nocobase;

--
-- Name: vi_scenario_base; Type: TABLE; Schema: public; Owner: nocobase
--

CREATE TABLE public.vi_scenario_base (
    id bigint NOT NULL,
    name text,
    is_base boolean,
    sort integer,
    volume_factor double precision,
    price_factor double precision,
    cost_factor double precision,
    discount_rate double precision,
    terminal_growth double precision,
    nature text,
    description text,
    model_id bigint,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    ronic double precision,
    sotp_multiple double precision,
    probability double precision
);


ALTER TABLE public.vi_scenario_base OWNER TO nocobase;

--
-- Name: TABLE vi_scenario_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_scenario_base IS '情景：各情景对逐年假设的整体调整；引用【估值模型】；被【分部估值项】【经营分部估值】【预测计算】【估值结论】【分部加总估值】【自动检查】引用。情景＝对逐年假设的整体调整：业务量、单价、付现成本乘以系数，折现率与永续增长按情景设置。';


--
-- Name: COLUMN vi_scenario_base.name; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.name IS '情景';


--
-- Name: COLUMN vi_scenario_base.is_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.is_base IS '基准情景：敏感性分析和单参数试验以基准情景为起点';


--
-- Name: COLUMN vi_scenario_base.sort; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.sort IS '排序';


--
-- Name: COLUMN vi_scenario_base.volume_factor; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.volume_factor IS '业务量系数：1＝不调整；0.9＝业务量−10%';


--
-- Name: COLUMN vi_scenario_base.price_factor; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.price_factor IS '单价系数';


--
-- Name: COLUMN vi_scenario_base.cost_factor; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.cost_factor IS '付现成本系数';


--
-- Name: COLUMN vi_scenario_base.discount_rate; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.discount_rate IS '折现率（留空＝基准折现率）（小数，0.05＝5%）';


--
-- Name: COLUMN vi_scenario_base.terminal_growth; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.terminal_growth IS '永续增长率（小数，0.05＝5%）';


--
-- Name: COLUMN vi_scenario_base.nature; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.nature IS '假设性质';


--
-- Name: COLUMN vi_scenario_base.description; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.description IS '情景说明';


--
-- Name: COLUMN vi_scenario_base.model_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.model_id IS '估值模型（关联 估值模型）';


--
-- Name: COLUMN vi_scenario_base.ronic; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.ronic IS '新增投资回报率：分部加总推导合理倍数用：P/E＝(1−g÷新增投资回报率)÷(r−g)（小数，0.05＝5%）';


--
-- Name: COLUMN vi_scenario_base.sotp_multiple; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.sotp_multiple IS '合理倍数（手填）：填了就用手填值，留空则按公式推导';


--
-- Name: COLUMN vi_scenario_base.probability; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_scenario_base.probability IS '情景概率：分部加总的概率加权价值用；同一模型各情景合计应为 100%，留空＝不加权（小数，0.05＝5%）';


--
-- Name: vi_scenario_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_scenario_calc AS
 SELECT s.id,
    COALESCE(s.discount_rate, mc.base_discount_rate) AS eff_discount_rate
   FROM (public.vi_scenario_base s
     LEFT JOIN public.vi_model_calc mc ON ((mc.id = s.model_id)));


ALTER VIEW public.vi_scenario_calc OWNER TO nocobase;

--
-- Name: vi_projection; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_projection AS
 WITH j AS (
         SELECT s.id AS scenario_id,
            s.model_id,
            s.name AS scenario_name,
            s.is_base,
            s.sort,
            s.volume_factor,
            s.price_factor,
            s.cost_factor,
            sc.eff_discount_rate AS r,
            m.base_year,
            m.terminal_year,
            m.shares,
            m.name AS model_name,
            co.name AS company_name,
            m.company_id,
            f.year,
            (f.volume * s.volume_factor) AS volume,
            (f.price * s.price_factor) AS price,
            (f.cash_cost * s.cost_factor) AS cash_cost,
            f.depreciation,
            fc.interest,
            f.other_contrib,
            f.tax_rate,
            f.minority_share,
            f.payout,
            f.net_borrowing,
            fc.debt_close,
            fc.attrib_da,
            fc.cash_complete,
            f.noncash_gain_deduct,
            f.investee_cash_div,
            f.other_cash_adj,
            f.wc_increase,
            f.maint_capex,
            f.growth_capex,
            f.min_cash_topup
           FROM (((((public.vi_scenario_base s
             JOIN public.vi_scenario_calc sc ON ((sc.id = s.id)))
             JOIN public.vi_model_base m ON ((m.id = s.model_id)))
             LEFT JOIN public.vi_company_base co ON ((co.id = m.company_id)))
             JOIN public.vi_forecast_base f ON ((f.model_id = s.model_id)))
             JOIN public.vi_forecast_calc fc ON ((fc.id = f.id)))
        ), k AS (
         SELECT j.scenario_id,
            j.model_id,
            j.scenario_name,
            j.is_base,
            j.sort,
            j.volume_factor,
            j.price_factor,
            j.cost_factor,
            j.r,
            j.base_year,
            j.terminal_year,
            j.shares,
            j.model_name,
            j.company_name,
            j.company_id,
            j.year,
            j.volume,
            j.price,
            j.cash_cost,
            j.depreciation,
            j.interest,
            j.other_contrib,
            j.tax_rate,
            j.minority_share,
            j.payout,
            j.net_borrowing,
            j.debt_close,
            j.attrib_da,
            j.cash_complete,
            j.noncash_gain_deduct,
            j.investee_cash_div,
            j.other_cash_adj,
            j.wc_increase,
            j.maint_capex,
            j.growth_capex,
            j.min_cash_topup,
            (j.volume * j.price) AS revenue
           FROM j
        ), l AS (
         SELECT k.scenario_id,
            k.model_id,
            k.scenario_name,
            k.is_base,
            k.sort,
            k.volume_factor,
            k.price_factor,
            k.cost_factor,
            k.r,
            k.base_year,
            k.terminal_year,
            k.shares,
            k.model_name,
            k.company_name,
            k.company_id,
            k.year,
            k.volume,
            k.price,
            k.cash_cost,
            k.depreciation,
            k.interest,
            k.other_contrib,
            k.tax_rate,
            k.minority_share,
            k.payout,
            k.net_borrowing,
            k.debt_close,
            k.attrib_da,
            k.cash_complete,
            k.noncash_gain_deduct,
            k.investee_cash_div,
            k.other_cash_adj,
            k.wc_increase,
            k.maint_capex,
            k.growth_capex,
            k.min_cash_topup,
            k.revenue,
            ((((k.revenue - k.cash_cost) - k.depreciation) - k.interest) + k.other_contrib) AS pretax
           FROM k
        ), m AS (
         SELECT l.scenario_id,
            l.model_id,
            l.scenario_name,
            l.is_base,
            l.sort,
            l.volume_factor,
            l.price_factor,
            l.cost_factor,
            l.r,
            l.base_year,
            l.terminal_year,
            l.shares,
            l.model_name,
            l.company_name,
            l.company_id,
            l.year,
            l.volume,
            l.price,
            l.cash_cost,
            l.depreciation,
            l.interest,
            l.other_contrib,
            l.tax_rate,
            l.minority_share,
            l.payout,
            l.net_borrowing,
            l.debt_close,
            l.attrib_da,
            l.cash_complete,
            l.noncash_gain_deduct,
            l.investee_cash_div,
            l.other_cash_adj,
            l.wc_increase,
            l.maint_capex,
            l.growth_capex,
            l.min_cash_topup,
            l.revenue,
            l.pretax,
            (l.pretax * l.tax_rate) AS tax,
            ((l.pretax * ((1)::double precision - l.tax_rate)) * l.minority_share) AS minority,
            ((l.pretax * ((1)::double precision - l.tax_rate)) * ((1)::double precision - l.minority_share)) AS np_parent,
            ((1)::double precision / power(((1)::double precision + l.r), ((l.year - l.base_year))::double precision)) AS discount_factor
           FROM l
        ), n AS (
         SELECT m.scenario_id,
            m.model_id,
            m.scenario_name,
            m.is_base,
            m.sort,
            m.volume_factor,
            m.price_factor,
            m.cost_factor,
            m.r,
            m.base_year,
            m.terminal_year,
            m.shares,
            m.model_name,
            m.company_name,
            m.company_id,
            m.year,
            m.volume,
            m.price,
            m.cash_cost,
            m.depreciation,
            m.interest,
            m.other_contrib,
            m.tax_rate,
            m.minority_share,
            m.payout,
            m.net_borrowing,
            m.debt_close,
            m.attrib_da,
            m.cash_complete,
            m.noncash_gain_deduct,
            m.investee_cash_div,
            m.other_cash_adj,
            m.wc_increase,
            m.maint_capex,
            m.growth_capex,
            m.min_cash_topup,
            m.revenue,
            m.pretax,
            m.tax,
            m.minority,
            m.np_parent,
            m.discount_factor,
            GREATEST((0)::double precision, (m.np_parent * m.payout)) AS dividend,
                CASE
                    WHEN m.cash_complete THEN ((((((m.np_parent + m.attrib_da) - m.noncash_gain_deduct) + m.investee_cash_div) + m.other_cash_adj) - m.wc_increase) - m.maint_capex)
                    ELSE NULL::double precision
                END AS owner_earnings
           FROM m
        ), o AS (
         SELECT n.scenario_id,
            n.model_id,
            n.scenario_name,
            n.is_base,
            n.sort,
            n.volume_factor,
            n.price_factor,
            n.cost_factor,
            n.r,
            n.base_year,
            n.terminal_year,
            n.shares,
            n.model_name,
            n.company_name,
            n.company_id,
            n.year,
            n.volume,
            n.price,
            n.cash_cost,
            n.depreciation,
            n.interest,
            n.other_contrib,
            n.tax_rate,
            n.minority_share,
            n.payout,
            n.net_borrowing,
            n.debt_close,
            n.attrib_da,
            n.cash_complete,
            n.noncash_gain_deduct,
            n.investee_cash_div,
            n.other_cash_adj,
            n.wc_increase,
            n.maint_capex,
            n.growth_capex,
            n.min_cash_topup,
            n.revenue,
            n.pretax,
            n.tax,
            n.minority,
            n.np_parent,
            n.discount_factor,
            n.dividend,
            n.owner_earnings,
            ((n.owner_earnings - n.growth_capex) + n.net_borrowing) AS fcfe
           FROM n
        )
 SELECT ((scenario_id * 10000) + year) AS id,
    scenario_id,
    model_id,
    company_id,
    company_name,
    model_name,
    scenario_name,
    is_base,
    sort,
    year,
    base_year,
    terminal_year,
    shares,
    volume,
    price,
    revenue,
    cash_cost,
    depreciation,
    interest,
    other_contrib,
    pretax,
    tax,
    minority,
    np_parent,
    payout,
    dividend,
    (dividend / NULLIF(shares, (0)::double precision)) AS dps,
    r AS discount_rate,
    discount_factor,
    (dividend * discount_factor) AS dividend_pv,
    owner_earnings,
    fcfe,
    LEAST(dividend, GREATEST((0)::double precision, (fcfe - min_cash_topup))) AS cash_supported_div,
    GREATEST((0)::double precision, ((dividend + min_cash_topup) - fcfe)) AS funding_gap,
    (LEAST(dividend, GREATEST((0)::double precision, (fcfe - min_cash_topup))) * discount_factor) AS cash_div_pv,
    debt_close,
    cash_complete
   FROM o;


ALTER VIEW public.vi_projection OWNER TO nocobase;

--
-- Name: vi_balance; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_balance AS
 WITH j AS (
         SELECT p.id,
            p.scenario_id,
            p.model_id,
            p.company_id,
            p.company_name,
            p.model_name,
            p.scenario_name,
            p.is_base,
            p.sort,
            p.year,
            p.np_parent,
            p.dividend,
            p.minority,
            p.payout,
            p.pretax,
            p.interest,
            p.depreciation,
            p.debt_close,
            (f.maint_capex + f.growth_capex) AS capex_total,
            (f.noncash_gain_deduct - f.investee_cash_div) AS lt_change,
            m.opening_op_assets,
            m.opening_lt_invest,
            m.opening_equity,
            m.opening_minority,
            m.opening_debt
           FROM ((public.vi_projection p
             JOIN public.vi_forecast_base f ON (((f.model_id = p.model_id) AND (f.year = p.year))))
             JOIN public.vi_model_base m ON ((m.id = p.model_id)))
        ), c AS (
         SELECT j.id,
            j.scenario_id,
            j.model_id,
            j.company_id,
            j.company_name,
            j.model_name,
            j.scenario_name,
            j.is_base,
            j.sort,
            j.year,
            j.np_parent,
            j.dividend,
            j.minority,
            j.payout,
            j.pretax,
            j.interest,
            j.depreciation,
            j.debt_close,
            j.capex_total,
            j.lt_change,
            j.opening_op_assets,
            j.opening_lt_invest,
            j.opening_equity,
            j.opening_minority,
            j.opening_debt,
            (j.opening_op_assets + sum((j.capex_total - j.depreciation)) OVER w) AS op_assets_close,
            (j.opening_lt_invest + sum(j.lt_change) OVER w) AS lt_invest_close,
            (j.opening_equity + sum((j.np_parent - j.dividend)) OVER w) AS equity_close,
            (j.opening_minority + sum((j.minority * ((1)::double precision - j.payout))) OVER w) AS minority_close
           FROM j
          WINDOW w AS (PARTITION BY j.scenario_id ORDER BY j.year ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
        ), d AS (
         SELECT c.id,
            c.scenario_id,
            c.model_id,
            c.company_id,
            c.company_name,
            c.model_name,
            c.scenario_name,
            c.is_base,
            c.sort,
            c.year,
            c.np_parent,
            c.dividend,
            c.minority,
            c.payout,
            c.pretax,
            c.interest,
            c.depreciation,
            c.debt_close,
            c.capex_total,
            c.lt_change,
            c.opening_op_assets,
            c.opening_lt_invest,
            c.opening_equity,
            c.opening_minority,
            c.opening_debt,
            c.op_assets_close,
            c.lt_invest_close,
            c.equity_close,
            c.minority_close,
            COALESCE(lag(c.op_assets_close) OVER s, c.opening_op_assets) AS op_assets_open,
            COALESCE(lag(c.equity_close) OVER s, c.opening_equity) AS equity_open,
            ((((c.equity_close + c.minority_close) + c.debt_close) - c.op_assets_close) - c.lt_invest_close) AS other_net_assets
           FROM c
          WINDOW s AS (PARTITION BY c.scenario_id ORDER BY c.year)
        )
 SELECT id,
    scenario_id,
    model_id,
    company_id,
    company_name,
    model_name,
    scenario_name,
    is_base,
    sort,
    year,
    op_assets_open,
    capex_total,
    depreciation,
    op_assets_close,
    lt_invest_close,
    debt_close,
    equity_open,
    np_parent,
    dividend,
    equity_close,
    minority_close,
    other_net_assets,
    (other_net_assets - COALESCE(lag(other_net_assets) OVER s, ((((opening_equity + opening_minority) + opening_debt) - opening_op_assets) - opening_lt_invest))) AS other_net_change,
    (np_parent / NULLIF(((equity_open + equity_close) / (2)::double precision), (0)::double precision)) AS roe,
    (debt_close / NULLIF(((debt_close + equity_close) + minority_close), (0)::double precision)) AS debt_to_capital,
    ((pretax + interest) / NULLIF(interest, (0)::double precision)) AS interest_cover,
    (debt_close / NULLIF(((pretax + interest) + depreciation), (0)::double precision)) AS debt_to_ebitda
   FROM d
  WINDOW s AS (PARTITION BY scenario_id ORDER BY year);


