ALTER TABLE public.vi_risk_base OWNER TO nocobase;

--
-- Name: TABLE vi_risk_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_risk_base IS '风险分析：可能让这笔投资亏钱的事件；引用【事实摘录】【核心论点】【假设依据】【跟踪事项】；被【自动检查】引用。会让这笔投资亏钱的不利事件：传导路径、可能性×冲击（自动定级）、量化影响、缓冲因素、在估值里怎么处理、预警信号与触发后应对。风险是论点失败或外部冲击的“事件”，论证本身仍在核心论点里，这里只关联会被削弱的论点；落到参数的关联假设依据，盯什么关联跟踪事项。';


--
-- Name: COLUMN vi_risk_base.code; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.code IS '编号：如 R1';


--
-- Name: COLUMN vi_risk_base.title; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.title IS '风险：写成会发生的不利事件，如“连续枯水：年发电量两年以上低于 2,700 亿千瓦时”';


--
-- Name: COLUMN vi_risk_base.category; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.category IS '类别（可选：行业与竞争、技术与替代、经营与执行、财务与资产质量、政策与监管、治理与资本配置、宏观与环境、估值与市场）';


--
-- Name: COLUMN vi_risk_base.mechanism; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.mechanism IS '传导路径：从事件到收入、利润、现金、估值的路径';


--
-- Name: COLUMN vi_risk_base.probability; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.probability IS '可能性：未来三年内发生的可能性（可选：高、中、低）';


--
-- Name: COLUMN vi_risk_base.impact; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.impact IS '冲击：发生后对每股价值的冲击：高＝超过 20%，中＝5%—20%，低＝5% 以内（可选：高、中、低）';


--
-- Name: COLUMN vi_risk_base.horizon; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.horizon IS '时间窗口（可选：1 年内、1—3 年、3 年以上）';


--
-- Name: COLUMN vi_risk_base.trend; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.trend IS '趋势（可选：上升、稳定、下降）';


--
-- Name: COLUMN vi_risk_base.impact_estimate; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.impact_estimate IS '影响测算：能量化的写数：对利润、现金或每股价值的影响（可引用单参数试验、情景）';


--
-- Name: COLUMN vi_risk_base.mitigants; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.mitigants IS '缓冲因素：什么能限制损失';


--
-- Name: COLUMN vi_risk_base.treatment; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.treatment IS '估值处理：这项风险在估值里怎么体现；未计入的要在影响测算里说明为什么（可选：已计入基准情景、已计入悲观情景、体现在折现率或门槛、未计入估值）';


--
-- Name: COLUMN vi_risk_base.early_warning; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.early_warning IS '预警信号：看什么、到什么程度算预警；已建跟踪事项的在“预警跟踪事项”里关联';


--
-- Name: COLUMN vi_risk_base.response; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.response IS '触发后应对：复核哪条论点或假设依据、要不要改参数（研究预警，不是交易指令）';


--
-- Name: COLUMN vi_risk_base.status; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.status IS '状态（可选：监控中、已部分发生、已发生、已缓解、已解除）';


--
-- Name: COLUMN vi_risk_base.company_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_risk_base.company_id IS '公司（关联 公司）';


--
-- Name: vi_risk_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_risk_calc AS
 SELECT r.id,
        CASE
            WHEN (s.score IS NULL) THEN NULL::text
            WHEN (s.score >= 6) THEN '重大'::text
            WHEN (s.score >= 3) THEN '重要'::text
            ELSE '一般'::text
        END AS level,
    ( SELECT string_agg(((t.code || ' '::text) || COALESCE(t.status, '未裁决'::text)), '；'::text ORDER BY t.code) AS string_agg
           FROM (public.vi_lnk_risk_theses l
             JOIN public.vi_thesis_base t ON ((t.id = l.thesis_id)))
          WHERE (l.risk_id = r.id)) AS thesis_verdicts
   FROM (public.vi_risk_base r
     CROSS JOIN LATERAL ( SELECT (
                CASE r.probability
                    WHEN '高'::text THEN 3
                    WHEN '中'::text THEN 2
                    WHEN '低'::text THEN 1
                    ELSE NULL::integer
                END *
                CASE r.impact
                    WHEN '高'::text THEN 3
                    WHEN '中'::text THEN 2
                    WHEN '低'::text THEN 1
                    ELSE NULL::integer
                END) AS score) s);


ALTER VIEW public.vi_risk_calc OWNER TO nocobase;

