--
-- Name: COLUMN vi_sotp_item_base.amount; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_item_base.amount IS '金额（亿元）：填正数，类别决定加减：现金与对外投资为加，其余为减；“其他调整”按填写的正负号';


--
-- Name: COLUMN vi_sotp_item_base.haircut; Type: COMMENT; Schema: public; Owner: nocobase
