COMMENT ON COLUMN public.vi_sotp_item_base.haircut IS '折价：对金额打的折扣，如对外投资的持有折价与处置税费（小数，0.05＝5%）';


--
-- Name: COLUMN vi_sotp_item_base.as_of; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_item_base.as_of IS '截至';


--
-- Name: COLUMN vi_sotp_item_base.basis; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_item_base.basis IS '依据';


--
-- Name: COLUMN vi_sotp_item_base.model_id; Type: COMMENT; Schema: public; Owner: nocobase
