COMMENT ON COLUMN public.vi_sotp_item_base.scenario_id IS '适用情景（关联 情景）';


--
-- Name: vi_sotp_item_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_sotp_item_calc AS
 SELECT i.id,
    (
        CASE
            WHEN (i.kind = '其他调整'::text) THEN i.amount
            WHEN (i.kind = ANY (ARRAY['现金及等价物'::text, '对外投资'::text])) THEN abs(i.amount)
            ELSE (- abs(i.amount))
        END * ((1)::double precision - COALESCE(i.haircut, (0)::double precision))) AS signed_value,
    COALESCE(s.name, '全部情景'::text) AS scope
   FROM (public.vi_sotp_item_base i
     LEFT JOIN public.vi_scenario_base s ON ((s.id = i.scenario_id)));


ALTER VIEW public.vi_sotp_item_calc OWNER TO nocobase;

