--
-- Name: TABLE vi_sotp_segment_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_sotp_segment_base IS '经营分部估值：分部加总里每个经营业务的估值；引用【事实摘录】【估值模型】【情景】；被【分部加总估值】【自动检查】引用。分部加总里的经营业务，按发展阶段各用一种方法：成熟或周期业务用“盈利×倍数”（正常化盈利）；成长业务用“稳态折现”（稳态年盈利×退出倍数折回今天，加上到稳态前的期间现金流）；投入期业务用“承诺投入”（只计已承诺的成本，回报不计入）。一行一个分部；适用情景留空＝所有情景，同编号可按情景另写一行。';


--
-- Name: COLUMN vi_sotp_segment_base.code; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.code IS '编号：如 S1；同一编号可按情景各写一行';


--
-- Name: COLUMN vi_sotp_segment_base.name; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.name IS '分部';


--
-- Name: COLUMN vi_sotp_segment_base.method; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.method IS '估值方法：盈利×倍数＝成熟或周期业务；稳态折现＝成长业务；承诺投入＝投入期业务（负值）（可选：盈利×倍数、稳态折现、承诺投入）';


--
-- Name: COLUMN vi_sotp_segment_base.stage; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.stage IS '发展阶段：如 成熟·周期底部、成长·规模爬坡、投入期';


--
-- Name: COLUMN vi_sotp_segment_base.earn_year; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.earn_year IS '盈利年份：盈利×倍数＝正常化盈利所在年份；稳态折现＝稳态年份。价值按“该年年初价值＝该年盈利×倍数”折回资产负债日；资产负债日之后第一个完整年度不折现';


--
