--
-- Name: COLUMN vi_sotp_segment_base.op_margin; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.op_margin IS '经营利润率：已扣股权激励，不含利息、投资收益与补贴（小数，0.05＝5%）';


--
-- Name: COLUMN vi_sotp_segment_base.tax_rate; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.tax_rate IS '所得税率：承诺投入填研发加计扣除后的实际抵税率（小数，0.05＝5%）';


--
-- Name: COLUMN vi_sotp_segment_base.attrib; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.attrib IS '归母比例：留空＝100%（小数，0.05＝5%）';


--
-- Name: COLUMN vi_sotp_segment_base.multiple; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.multiple IS '倍数（手填）：填了就用手填值；留空按 (1−g÷新增投资回报率)÷(r−g)';


--
-- Name: COLUMN vi_sotp_segment_base.ronic; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.ronic IS '新增投资回报率：留空＝情景的新增投资回报率（小数，0.05＝5%）';


--
-- Name: COLUMN vi_sotp_segment_base.growth; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.growth IS '永续增长率：留空＝情景的永续增长率；承诺投入＝承诺期后年成本的增长率（小数，0.05＝5%）';


--
-- Name: COLUMN vi_sotp_segment_base.discount_rate; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.discount_rate IS '折现率：留空＝情景折现率；成长业务可加执行风险溢价（小数，0.05＝5%）';


--
-- Name: COLUMN vi_sotp_segment_base.interim_cash; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.interim_cash IS '期间现金流（亿元）：资产负债日到盈利年份年初之间的税后累计现金流（负数＝净投入），按期中折现';


--
-- Name: COLUMN vi_sotp_segment_base.commit_amount; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.commit_amount IS '承诺投入·剩余金额（亿元）：资产负债日之后尚需投入的税前金额（扣除相关收入）';


--
-- Name: COLUMN vi_sotp_segment_base.commit_years; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.commit_years IS '承诺投入·剩余年数';


--
-- Name: COLUMN vi_sotp_segment_base.ongoing_cost; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.ongoing_cost IS '承诺期后年成本（亿元）：承诺期结束后每年仍需承担、没有回报覆盖的税前净成本；留空＝0';


--
-- Name: COLUMN vi_sotp_segment_base.basis; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.basis IS '依据';


--
-- Name: COLUMN vi_sotp_segment_base.model_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.model_id IS '估值模型（关联 估值模型）';


--
-- Name: COLUMN vi_sotp_segment_base.scenario_id; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.scenario_id IS '适用情景（关联 情景）';


--
-- Name: COLUMN vi_sotp_segment_base.direct_value; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_sotp_segment_base.direct_value IS '直接估值（亿元）：直接估值：按可比公司、交易价格或主观判断给出的整体价值（已含该业务未来的投入与回报），不折现';


--
-- Name: vi_sotp_segment_val; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_sotp_segment_val AS
 WITH pick AS (
         SELECT DISTINCT ON (s.id, g.code) s.id AS scenario_id,
            s.model_id,
            s.name AS scenario_name,
            COALESCE(s.is_base, false) AS is_base,
            g.id AS segment_id,
            g.code,
            g.name,
            g.method,
            g.earn_year,
            g.revenue,
            g.op_margin,
            COALESCE(g.tax_rate, (0)::double precision) AS tax_rate,
            COALESCE(g.attrib, (1)::double precision) AS attrib,
            g.multiple,
            COALESCE(g.ronic, s.ronic) AS ronic,
            COALESCE(g.growth, s.terminal_growth) AS growth,
            COALESCE(g.discount_rate, x.eff_discount_rate) AS r,
            COALESCE(g.interim_cash, (0)::double precision) AS interim_cash,
            COALESCE(g.commit_amount, (0)::double precision) AS commit_amount,
            g.commit_years,
            COALESCE(g.ongoing_cost, (0)::double precision) AS ongoing_cost,
            g.direct_value,
            m.sotp_as_of AS as_of
           FROM (((public.vi_scenario_base s
             JOIN public.vi_scenario_calc x ON ((x.id = s.id)))
             JOIN public.vi_model_base m ON ((m.id = s.model_id)))
             JOIN public.vi_sotp_segment_base g ON (((g.model_id = s.model_id) AND ((g.scenario_id = s.id) OR (g.scenario_id IS NULL)))))
          ORDER BY s.id, g.code, (g.scenario_id IS NULL)
        ), a AS (
         SELECT pick.scenario_id,
            pick.model_id,
            pick.scenario_name,
            pick.is_base,
            pick.segment_id,
            pick.code,
            pick.name,
            pick.method,
            pick.earn_year,
            pick.revenue,
            pick.op_margin,
            pick.tax_rate,
            pick.attrib,
            pick.multiple,
            pick.ronic,
            pick.growth,
            pick.r,
            pick.interim_cash,
            pick.commit_amount,
            pick.commit_years,
            pick.ongoing_cost,
            pick.direct_value,
            pick.as_of,
                CASE
                    WHEN (pick.method = '承诺投入'::text) THEN (((- pick.ongoing_cost) * ((1)::double precision - pick.tax_rate)) * pick.attrib)
                    WHEN (pick.method = '直接估值'::text) THEN NULL::double precision
                    ELSE (((pick.revenue * pick.op_margin) * ((1)::double precision - pick.tax_rate)) * pick.attrib)
                END AS earnings,
                CASE
                    WHEN ((pick.method = ANY (ARRAY['盈利×倍数'::text, '稳态折现'::text])) AND (pick.ronic > (0)::double precision) AND (pick.r > pick.growth)) THEN (((1)::double precision - (pick.growth / pick.ronic)) / (pick.r - pick.growth))
                    ELSE NULL::double precision
                END AS formula_multiple,
                CASE
                    WHEN (pick.method = '承诺投入'::text) THEN pick.commit_years
                    WHEN (pick.method = '直接估值'::text) THEN (0)::double precision
                    ELSE GREATEST((0)::double precision, ((((make_date((pick.earn_year - 1), 12, 31) - pick.as_of))::numeric / 365.25))::double precision)
                END AS tau
           FROM pick
        ), b AS (
         SELECT a.scenario_id,
            a.model_id,
            a.scenario_name,
            a.is_base,
            a.segment_id,
            a.code,
            a.name,
            a.method,
            a.earn_year,
            a.revenue,
            a.op_margin,
            a.tax_rate,
            a.attrib,
            a.multiple,
            a.ronic,
            a.growth,
            a.r,
            a.interim_cash,
            a.commit_amount,
            a.commit_years,
            a.ongoing_cost,
            a.direct_value,
            a.as_of,
            a.earnings,
            a.formula_multiple,
            a.tau,
                CASE
                    WHEN (a.method = ANY (ARRAY['盈利×倍数'::text, '稳态折现'::text])) THEN COALESCE(a.multiple, a.formula_multiple)
                    ELSE NULL::double precision
                END AS multiple_used
           FROM a
        ), c AS (
         SELECT b.scenario_id,
            b.model_id,
            b.scenario_name,
            b.is_base,
            b.segment_id,
            b.code,
            b.name,
            b.method,
            b.earn_year,
            b.revenue,
            b.op_margin,
            b.tax_rate,
            b.attrib,
            b.multiple,
            b.ronic,
            b.growth,
            b.r,
            b.interim_cash,
            b.commit_amount,
            b.commit_years,
            b.ongoing_cost,
            b.direct_value,
            b.as_of,
            b.earnings,
            b.formula_multiple,
            b.tau,
            b.multiple_used,
                CASE
                    WHEN (b.method = '承诺投入'::text) THEN
                    CASE
                        WHEN (b.ongoing_cost = (0)::double precision) THEN (0)::double precision
                        WHEN ((b.r > b.growth) AND (b.tau IS NOT NULL)) THEN (((((- b.ongoing_cost) * ((1)::double precision - b.tax_rate)) * b.attrib) / (b.r - b.growth)) / power(((1)::double precision + b.r), b.tau))
                        ELSE NULL::double precision
                    END
                    WHEN (b.method = '直接估值'::text) THEN b.direct_value
                    ELSE ((b.earnings * b.multiple_used) / power(((1)::double precision + b.r), b.tau))
                END AS terminal_pv,
                CASE
                    WHEN (b.method = '承诺投入'::text) THEN
                    CASE
                        WHEN (b.commit_amount = (0)::double precision) THEN (0)::double precision
                        WHEN ((b.tau > (0)::double precision) AND (b.r > (0)::double precision)) THEN (((((- (b.commit_amount / b.tau)) * ((1)::double precision - b.tax_rate)) * b.attrib) * ((1)::double precision - power(((1)::double precision + b.r), (- b.tau)))) / b.r)
                        ELSE NULL::double precision
                    END
                    WHEN (b.method = '直接估值'::text) THEN (0)::double precision
                    ELSE (b.interim_cash / power(((1)::double precision + b.r), (b.tau / (2)::double precision)))
                END AS interim_pv,
                CASE
                    WHEN (b.method = ANY (ARRAY['盈利×倍数'::text, '稳态折现'::text])) THEN (b.earnings / power(((1)::double precision + b.r), b.tau))
                    ELSE NULL::double precision
                END AS earn_pv
           FROM b
        )
 SELECT ((scenario_id * 100000) + segment_id) AS id,
    scenario_id,
    model_id,
    scenario_name,
    is_base,
    segment_id,
    code,
    name,
    method,
    earn_year,
    revenue,
    op_margin,
    tax_rate,
    attrib,
    r,
    growth,
    ronic,
    earnings,
    formula_multiple,
    multiple_used,
    tau,
    interim_cash,
    commit_amount,
    commit_years,
    ongoing_cost,
    direct_value,
    terminal_pv,
    interim_pv,
    earn_pv,
    (terminal_pv + interim_pv) AS value
   FROM c;


ALTER VIEW public.vi_sotp_segment_val OWNER TO nocobase;

--
-- Name: vi_valuation_cf; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_valuation_cf AS
 SELECT s.id AS scenario_id,
    s.model_id,
    s.terminal_growth AS cf_g,
    m.required_return,
    mc.years_elapsed AS cf_elapsed,
    array_agg((p.dividend / NULLIF(m.shares, (0)::double precision)) ORDER BY p.year) AS divs,
    array_agg((p.cash_supported_div / NULLIF(m.shares, (0)::double precision)) ORDER BY p.year) AS cash_divs,
    array_agg((((p.year - m.base_year))::numeric - mc.years_elapsed) ORDER BY p.year) AS taus,
    max((p.dividend / NULLIF(m.shares, (0)::double precision))) FILTER (WHERE (p.year = m.terminal_year)) AS td,
    max((p.cash_supported_div / NULLIF(m.shares, (0)::double precision))) FILTER (WHERE (p.year = m.terminal_year)) AS tcd,
    (((m.terminal_year - m.base_year))::numeric - mc.years_elapsed) AS ttau
   FROM (((public.vi_scenario_base s
     JOIN public.vi_model_base m ON ((m.id = s.model_id)))
     JOIN public.vi_model_calc mc ON ((mc.id = m.id)))
     JOIN public.vi_projection p ON (((p.scenario_id = s.id) AND ((p.year >= (m.base_year + 1)) AND (p.year <= m.terminal_year)))))
  GROUP BY s.id, s.model_id, s.terminal_growth, m.required_return, mc.years_elapsed, m.terminal_year, m.base_year;


ALTER VIEW public.vi_valuation_cf OWNER TO nocobase;

--
-- Name: vi_valuation; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_valuation AS
 WITH a AS (
         SELECT s.id,
            s.model_id,
            s.name AS scenario_name,
            COALESCE(s.is_base, false) AS is_base,
            s.sort,
            sc.eff_discount_rate AS r,
            s.terminal_growth AS g,
            m.base_year AS b,
            m.terminal_year AS t,
            m.shares,
            m.margin_low,
            m.margin_high,
            m.name AS model_name,
            m.company_id,
            co.name AS company_name,
            cc.latest_price,
            cc.latest_price_date,
            mc.years_elapsed,
            ( SELECT count(*) AS count
                   FROM public.vi_projection p
                  WHERE ((p.scenario_id = s.id) AND ((p.year >= (m.base_year + 1)) AND (p.year <= m.terminal_year)) AND (p.np_parent IS NOT NULL))) AS n_years,
            ( SELECT count(*) AS count
                   FROM public.vi_projection p
                  WHERE ((p.scenario_id = s.id) AND ((p.year >= (m.base_year + 1)) AND (p.year <= m.terminal_year)) AND (p.cash_supported_div IS NOT NULL))) AS cash_years,
            ( SELECT sum(p.dividend_pv) AS sum
                   FROM public.vi_projection p
                  WHERE ((p.scenario_id = s.id) AND ((p.year >= (m.base_year + 1)) AND (p.year <= m.terminal_year)))) AS pv_explicit,
            ( SELECT sum(p.cash_div_pv) AS sum
                   FROM public.vi_projection p
                  WHERE ((p.scenario_id = s.id) AND ((p.year >= (m.base_year + 1)) AND (p.year <= m.terminal_year)))) AS cash_pv,
            ( SELECT p.dividend
                   FROM public.vi_projection p
                  WHERE ((p.scenario_id = s.id) AND (p.year = m.terminal_year))) AS terminal_div,
            ( SELECT p.cash_supported_div
                   FROM public.vi_projection p
                  WHERE ((p.scenario_id = s.id) AND (p.year = m.terminal_year))) AS terminal_cash_div
           FROM (((((public.vi_scenario_base s
             JOIN public.vi_scenario_calc sc ON ((sc.id = s.id)))
             JOIN public.vi_model_base m ON ((m.id = s.model_id)))
             JOIN public.vi_model_calc mc ON ((mc.id = m.id)))
             LEFT JOIN public.vi_company_base co ON ((co.id = m.company_id)))
             LEFT JOIN public.vi_company_calc cc ON ((cc.id = m.company_id)))
        ), b AS (
         SELECT a.id,
            a.model_id,
            a.scenario_name,
            a.is_base,
            a.sort,
            a.r,
            a.g,
            a.b,
            a.t,
            a.shares,
            a.margin_low,
            a.margin_high,
            a.model_name,
            a.company_id,
            a.company_name,
            a.latest_price,
            a.latest_price_date,
            a.years_elapsed,
            a.n_years,
            a.cash_years,
            a.pv_explicit,
            a.cash_pv,
            a.terminal_div,
            a.terminal_cash_div,
            (a.n_years = (a.t - a.b)) AS complete,
                CASE
                    WHEN (a.r > a.g) THEN (((a.terminal_div * ((1)::double precision + a.g)) / (a.r - a.g)) / power(((1)::double precision + a.r), ((a.t - a.b))::double precision))
                    ELSE NULL::double precision
                END AS terminal_pv,
                CASE
                    WHEN (a.r > a.g) THEN (((a.terminal_cash_div * ((1)::double precision + a.g)) / (a.r - a.g)) / power(((1)::double precision + a.r), ((a.t - a.b))::double precision))
                    ELSE NULL::double precision
                END AS terminal_cash_pv
           FROM a
        ), c AS (
         SELECT b.id,
            b.model_id,
            b.scenario_name,
            b.is_base,
            b.sort,
            b.r,
            b.g,
            b.b,
            b.t,
            b.shares,
            b.margin_low,
            b.margin_high,
            b.model_name,
            b.company_id,
            b.company_name,
            b.latest_price,
            b.latest_price_date,
            b.years_elapsed,
            b.n_years,
            b.cash_years,
            b.pv_explicit,
            b.cash_pv,
            b.terminal_div,
            b.terminal_cash_div,
            b.complete,
            b.terminal_pv,
            b.terminal_cash_pv,
                CASE
                    WHEN (b.complete AND (b.r > b.g) AND (b.shares > (0)::double precision)) THEN ((b.pv_explicit + b.terminal_pv) / b.shares)
                    ELSE NULL::double precision
                END AS v0,
                CASE
                    WHEN ((b.cash_years = (b.t - b.b)) AND (b.r > b.g) AND (b.shares > (0)::double precision)) THEN ((b.cash_pv + b.terminal_cash_pv) / b.shares)
                    ELSE NULL::double precision
                END AS cv0
           FROM b
        ), d AS (
         SELECT c.id,
            c.model_id,
            c.scenario_name,
            c.is_base,
            c.sort,
            c.r,
            c.g,
            c.b,
            c.t,
            c.shares,
            c.margin_low,
            c.margin_high,
            c.model_name,
            c.company_id,
            c.company_name,
            c.latest_price,
            c.latest_price_date,
            c.years_elapsed,
            c.n_years,
            c.cash_years,
            c.pv_explicit,
            c.cash_pv,
            c.terminal_div,
            c.terminal_cash_div,
            c.complete,
            c.terminal_pv,
            c.terminal_cash_pv,
            c.v0,
            c.cv0,
            (c.v0 * power(((1)::double precision + c.r), (c.years_elapsed)::double precision)) AS v1,
            (c.cv0 * power(((1)::double precision + c.r), (c.years_elapsed)::double precision)) AS cv1,
            f.required_return AS req,
                CASE
                    WHEN c.complete THEN public.vi_pv(f.divs, (f.taus)::double precision[], f.td, (f.ttau)::double precision, c.g, f.required_return)
                    ELSE NULL::double precision
                END AS v_req,
                CASE
                    WHEN c.complete THEN public.vi_irr(f.divs, (f.taus)::double precision[], f.td, (f.ttau)::double precision, c.g, c.latest_price)
                    ELSE NULL::double precision
                END AS irr,
                CASE
                    WHEN (c.cash_years = (c.t - c.b)) THEN public.vi_irr(f.cash_divs, (f.taus)::double precision[], f.tcd, (f.ttau)::double precision, c.g, c.latest_price)
                    ELSE NULL::double precision
                END AS cash_irr
           FROM (c
             LEFT JOIN public.vi_valuation_cf f ON ((f.scenario_id = c.id)))
        )
 SELECT id,
    model_id,
    company_id,
    company_name,
    model_name,
    scenario_name,
    is_base,
    sort,
    r AS discount_rate,
    g AS terminal_growth,
    v0 AS value_base_date,
    v1 AS value_today,
    cv1 AS cash_value_today,
    pv_explicit,
    terminal_pv,
    (terminal_pv / NULLIF((pv_explicit + terminal_pv), (0)::double precision)) AS terminal_share,
    latest_price AS market_price,
    latest_price_date AS market_date,
    ((latest_price / NULLIF(v1, (0)::double precision)) - (1)::double precision) AS price_vs_value,
    (v1 * ((1)::double precision - margin_low)) AS watch_low,
    (v1 * ((1)::double precision - margin_high)) AS watch_high,
    complete AS years_complete,
    (cash_years)::integer AS cash_years,
    req AS required_return,
    v_req AS value_at_required,
    irr AS implied_irr,
    cash_irr AS cash_implied_irr,
    (irr - req) AS irr_spread,
    (
        CASE
            WHEN (NOT complete) THEN format('预测年份不完整：需要 %s—%s 年共 %s 年，现有 %s 年'::text, (b + 1), t, (t - b), n_years)
            WHEN (r <= g) THEN '折现率不大于永续增长率，不输出价值'::text
            ELSE (
            CASE
                WHEN ((irr IS NULL) OR (req IS NULL)) THEN ''::text
                ELSE format('按市场价 %s 元买入，隐含年化收益率 %s（现金支持口径 %s），%s要求收益率 %s；按要求收益率的最高买入价 %s 元。'::text, public.vi_fmt(latest_price), public.vi_pct(irr, 2), public.vi_pct(cash_irr, 2),
                CASE
                    WHEN (irr >= req) THEN '达到'::text
                    ELSE '低于'::text
                END, public.vi_pct(req, 1), public.vi_fmt(v_req))
            END || format('今天每股价值 %s 元（基准日 %s 元按 %s 滚动 %s 年）。%s%s'::text, public.vi_fmt(v1), public.vi_fmt(v0), public.vi_pct(r, 2), round(years_elapsed, 2),
            CASE
                WHEN (latest_price IS NULL) THEN '暂无市场价。'::text
                WHEN (latest_price > v1) THEN format('市场价 %s 元，高于今天价值 %s。'::text, public.vi_fmt(latest_price), public.vi_pct(((latest_price / v1) - (1)::double precision)))
                WHEN (latest_price > (v1 * ((1)::double precision - margin_low))) THEN format('市场价 %s 元，低于今天价值 %s，但未到低档关注价 %s 元。'::text, public.vi_fmt(latest_price), public.vi_pct(((1)::double precision - (latest_price / v1))), public.vi_fmt((v1 * ((1)::double precision - margin_low))))
                WHEN (latest_price > (v1 * ((1)::double precision - margin_high))) THEN format('市场价 %s 元，已低于低档关注价 %s 元。'::text, public.vi_fmt(latest_price), public.vi_fmt((v1 * ((1)::double precision - margin_low))))
                ELSE format('市场价 %s 元，已低于高档关注价 %s 元。'::text, public.vi_fmt(latest_price), public.vi_fmt((v1 * ((1)::double precision - margin_high))))
            END,
            CASE
                WHEN (cv1 IS NULL) THEN '现金桥接不完整，现金支持价值不输出。'::text
                WHEN (cv1 < v1) THEN format('现金支持价值 %s 元低于股息贴现价值，部分年份 FCFE 不足以支付计划股息。'::text, public.vi_fmt(cv1))
                ELSE ''::text
            END))
        END || ' 研究提示，不是交易指令。'::text) AS conclusion
   FROM d;


ALTER VIEW public.vi_valuation OWNER TO nocobase;

--
-- Name: vi_sotp; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_sotp AS
 WITH sc AS (
         SELECT s.id AS scenario_id,
            s.model_id,
            s.name AS scenario_name,
            COALESCE(s.is_base, false) AS is_base,
            s.sort,
            x.eff_discount_rate AS r,
            s.terminal_growth AS g,
            s.ronic,
            s.sotp_multiple,
            s.probability,
            m.sotp_year,
            m.sotp_core_adj,
            m.sotp_as_of,
            m.shares,
            m.margin_low,
            m.margin_high,
            m.company_id,
            m.name AS model_name,
            co.name AS company_name,
            cc.latest_price,
            cc.latest_fx
           FROM ((((public.vi_scenario_base s
             JOIN public.vi_scenario_calc x ON ((x.id = s.id)))
             JOIN public.vi_model_base m ON ((m.id = s.model_id)))
             LEFT JOIN public.vi_company_base co ON ((co.id = m.company_id)))
             LEFT JOIN public.vi_company_calc cc ON ((cc.id = m.company_id)))
          WHERE (((m.sotp_year IS NOT NULL) AND (EXISTS ( SELECT 1
                   FROM public.vi_sotp_item_base i
                  WHERE (i.model_id = m.id)))) OR (EXISTS ( SELECT 1
                   FROM public.vi_sotp_segment_base g
                  WHERE (g.model_id = m.id))))
        ), core AS (
         SELECT sc.scenario_id,
            sc.model_id,
            sc.scenario_name,
            sc.is_base,
            sc.sort,
            sc.r,
            sc.g,
            sc.ronic,
            sc.sotp_multiple,
            sc.probability,
            sc.sotp_year,
            sc.sotp_core_adj,
            sc.sotp_as_of,
            sc.shares,
            sc.margin_low,
            sc.margin_high,
            sc.company_id,
            sc.model_name,
            sc.company_name,
            sc.latest_price,
            sc.latest_fx,
            ((p.pretax - p.other_contrib) + p.interest) AS core_pretax,
            (((((p.pretax - p.other_contrib) + p.interest) * p.np_parent) / NULLIF(p.pretax, (0)::double precision)) + COALESCE(sc.sotp_core_adj, (0)::double precision)) AS core_earnings
           FROM (sc
             LEFT JOIN public.vi_projection p ON (((p.scenario_id = sc.scenario_id) AND (p.year = sc.sotp_year))))
        ), items AS (
         SELECT DISTINCT ON (c.scenario_id, i.code) c.scenario_id,
            i.kind,
            ic.signed_value
           FROM ((core c
             JOIN public.vi_sotp_item_base i ON (((i.model_id = c.model_id) AND ((i.scenario_id = c.scenario_id) OR (i.scenario_id IS NULL)))))
             JOIN public.vi_sotp_item_calc ic ON ((ic.id = i.id)))
          ORDER BY c.scenario_id, i.code, (i.scenario_id IS NULL)
        ), agg AS (
         SELECT items.scenario_id,
            sum(items.signed_value) FILTER (WHERE (items.kind = '现金及等价物'::text)) AS cash,
            sum(items.signed_value) FILTER (WHERE (items.kind = '带息负债'::text)) AS debt,
            sum(items.signed_value) FILTER (WHERE (items.kind = '经营所需现金'::text)) AS op_cash,
            sum(items.signed_value) FILTER (WHERE (items.kind = '资金汇出成本'::text)) AS repatriation,
            sum(items.signed_value) FILTER (WHERE (items.kind = '对外投资'::text)) AS investments,
            sum(items.signed_value) FILTER (WHERE (items.kind = ANY (ARRAY['少数股东权益'::text, '其他调整'::text]))) AS minority_other,
            sum(items.signed_value) AS noncore
           FROM items
          GROUP BY items.scenario_id
        ), segs AS (
         SELECT vi_sotp_segment_val.scenario_id,
            count(*) AS n_segments,
            count(*) FILTER (WHERE (vi_sotp_segment_val.value IS NULL)) AS n_incomplete,
            sum(vi_sotp_segment_val.value) AS segments_value,
            sum(vi_sotp_segment_val.value) FILTER (WHERE (vi_sotp_segment_val.method = '盈利×倍数'::text)) AS mature_value,
            sum(vi_sotp_segment_val.earnings) FILTER (WHERE (vi_sotp_segment_val.method = '盈利×倍数'::text)) AS mature_earnings,
            sum(vi_sotp_segment_val.earn_pv) FILTER (WHERE (vi_sotp_segment_val.method = '盈利×倍数'::text)) AS mature_earn_pv,
            sum(vi_sotp_segment_val.interim_pv) FILTER (WHERE (vi_sotp_segment_val.method = '盈利×倍数'::text)) AS mature_interim_pv,
            sum(vi_sotp_segment_val.value) FILTER (WHERE (vi_sotp_segment_val.method = '稳态折现'::text)) AS growth_value,
            sum(vi_sotp_segment_val.value) FILTER (WHERE (vi_sotp_segment_val.method = '承诺投入'::text)) AS invest_value,
            sum(vi_sotp_segment_val.value) FILTER (WHERE (vi_sotp_segment_val.method = '直接估值'::text)) AS direct_value
           FROM public.vi_sotp_segment_val
          GROUP BY vi_sotp_segment_val.scenario_id
        ), v AS (
         SELECT core.scenario_id,
            core.model_id,
            core.scenario_name,
            core.is_base,
            core.sort,
            core.r,
            core.g,
            core.ronic,
            core.sotp_multiple,
            core.probability,
            core.sotp_year,
            core.sotp_core_adj,
            core.sotp_as_of,
            core.shares,
            core.margin_low,
            core.margin_high,
            core.company_id,
            core.model_name,
            core.company_name,
            core.latest_price,
            core.latest_fx,
            core.core_pretax,
            core.core_earnings,
            a.cash,
            a.debt,
            a.op_cash,
            a.repatriation,
            a.investments,
            a.minority_other,
            COALESCE(a.noncore, (0)::double precision) AS noncore,
            (((COALESCE(a.cash, (0)::double precision) + COALESCE(a.debt, (0)::double precision)) + COALESCE(a.op_cash, (0)::double precision)) + COALESCE(a.repatriation, (0)::double precision)) AS usable_net_cash,
                CASE
                    WHEN ((core.ronic > (0)::double precision) AND (core.r > core.g)) THEN (((1)::double precision - (core.g / core.ronic)) / (core.r - core.g))
                    ELSE NULL::double precision
                END AS formula_multiple,
            COALESCE(sg.n_segments, (0)::bigint) AS n_segments,
            COALESCE(sg.n_incomplete, (0)::bigint) AS n_incomplete,
            sg.segments_value,
            sg.mature_value,
            sg.mature_earnings,
            sg.mature_earn_pv,
            sg.mature_interim_pv,
            sg.growth_value,
            sg.invest_value,
            sg.direct_value
           FROM ((core
             LEFT JOIN agg a USING (scenario_id))
             LEFT JOIN segs sg USING (scenario_id))
        ), w AS (
         SELECT v.scenario_id,
            v.model_id,
            v.scenario_name,
            v.is_base,
            v.sort,
            v.r,
            v.g,
            v.ronic,
            v.sotp_multiple,
            v.probability,
            v.sotp_year,
            v.sotp_core_adj,
            v.sotp_as_of,
            v.shares,
            v.margin_low,
            v.margin_high,
            v.company_id,
            v.model_name,
            v.company_name,
            v.latest_price,
            v.latest_fx,
            v.core_pretax,
            v.core_earnings,
            v.cash,
            v.debt,
            v.op_cash,
            v.repatriation,
            v.investments,
            v.minority_other,
            v.noncore,
            v.usable_net_cash,
            v.formula_multiple,
            v.n_segments,
            v.n_incomplete,
            v.segments_value,
            v.mature_value,
            v.mature_earnings,
            v.mature_earn_pv,
            v.mature_interim_pv,
            v.growth_value,
            v.invest_value,
            v.direct_value,
            COALESCE(v.sotp_multiple, v.formula_multiple) AS multiple
           FROM v
        ), x AS (
         SELECT w.scenario_id,
            w.model_id,
            w.scenario_name,
            w.is_base,
            w.sort,
            w.r,
            w.g,
            w.ronic,
            w.sotp_multiple,
            w.probability,
            w.sotp_year,
            w.sotp_core_adj,
            w.sotp_as_of,
            w.shares,
            w.margin_low,
            w.margin_high,
            w.company_id,
            w.model_name,
            w.company_name,
            w.latest_price,
            w.latest_fx,
            w.core_pretax,
            w.core_earnings,
            w.cash,
            w.debt,
            w.op_cash,
            w.repatriation,
            w.investments,
            w.minority_other,
            w.noncore,
            w.usable_net_cash,
            w.formula_multiple,
            w.n_segments,
            w.n_incomplete,
            w.segments_value,
            w.mature_value,
            w.mature_earnings,
            w.mature_earn_pv,
            w.mature_interim_pv,
            w.growth_value,
            w.invest_value,
            w.direct_value,
            w.multiple,
            (w.core_earnings * w.multiple) AS core_value,
                CASE
                    WHEN ((w.n_incomplete = 0) AND ((w.sotp_year IS NULL) OR ((w.core_earnings * w.multiple) IS NOT NULL))) THEN ((COALESCE((w.core_earnings * w.multiple), (0)::double precision) + COALESCE(w.segments_value, (0)::double precision)) + w.noncore)
                    ELSE NULL::double precision
                END AS equity_value
           FROM w
        ), y AS (
         SELECT x.scenario_id,
            x.model_id,
            x.scenario_name,
            x.is_base,
            x.sort,
            x.r,
            x.g,
            x.ronic,
            x.sotp_multiple,
            x.probability,
            x.sotp_year,
            x.sotp_core_adj,
            x.sotp_as_of,
            x.shares,
            x.margin_low,
            x.margin_high,
            x.company_id,
            x.model_name,
            x.company_name,
            x.latest_price,
            x.latest_fx,
            x.core_pretax,
            x.core_earnings,
            x.cash,
            x.debt,
            x.op_cash,
            x.repatriation,
            x.investments,
            x.minority_other,
            x.noncore,
            x.usable_net_cash,
            x.formula_multiple,
            x.n_segments,
            x.n_incomplete,
            x.segments_value,
            x.mature_value,
            x.mature_earnings,
            x.mature_earn_pv,
            x.mature_interim_pv,
            x.growth_value,
            x.invest_value,
            x.direct_value,
            x.multiple,
            x.core_value,
            x.equity_value,
            (x.equity_value / NULLIF(x.shares, (0)::double precision)) AS vps,
            (x.latest_price * x.shares) AS mcap
           FROM x
        ), z AS (
         SELECT y.scenario_id,
            y.model_id,
            y.scenario_name,
            y.is_base,
            y.sort,
            y.r,
            y.g,
            y.ronic,
            y.sotp_multiple,
            y.probability,
            y.sotp_year,
            y.sotp_core_adj,
            y.sotp_as_of,
            y.shares,
            y.margin_low,
            y.margin_high,
            y.company_id,
            y.model_name,
            y.company_name,
            y.latest_price,
            y.latest_fx,
            y.core_pretax,
            y.core_earnings,
            y.cash,
            y.debt,
            y.op_cash,
            y.repatriation,
            y.investments,
            y.minority_other,
            y.noncore,
            y.usable_net_cash,
            y.formula_multiple,
            y.n_segments,
            y.n_incomplete,
            y.segments_value,
            y.mature_value,
            y.mature_earnings,
            y.mature_earn_pv,
            y.mature_interim_pv,
            y.growth_value,
            y.invest_value,
            y.direct_value,
            y.multiple,
            y.core_value,
            y.equity_value,
            y.vps,
            y.mcap,
                CASE
                    WHEN ((count(*) OVER pm = count(y.probability) OVER pm) AND (count(*) OVER pm = count(y.vps) OVER pm)) THEN (sum((y.probability * y.vps)) OVER pm / NULLIF(sum(y.probability) OVER pm, (0)::double precision))
                    ELSE NULL::double precision
                END AS weighted_value,
                CASE
                    WHEN (y.mature_earn_pv > (0)::double precision) THEN (((((((y.mcap - y.noncore) - COALESCE(y.core_value, (0)::double precision)) - COALESCE(y.growth_value, (0)::double precision)) - COALESCE(y.invest_value, (0)::double precision)) - COALESCE(y.direct_value, (0)::double precision)) - y.mature_interim_pv) / y.mature_earn_pv)
                    ELSE NULL::double precision
                END AS implied_mature_multiple,
                CASE
                    WHEN (y.growth_value IS NOT NULL) THEN (((((y.mcap - y.noncore) - COALESCE(y.core_value, (0)::double precision)) - COALESCE(y.mature_value, (0)::double precision)) - COALESCE(y.invest_value, (0)::double precision)) - COALESCE(y.direct_value, (0)::double precision))
                    ELSE NULL::double precision
                END AS implied_growth_value,
            ((y.mature_value - y.mature_interim_pv) / NULLIF(y.mature_earn_pv, (0)::double precision)) AS mature_multiple
           FROM y
          WINDOW pm AS (PARTITION BY y.model_id)
        )
 SELECT z.scenario_id AS id,
    z.model_id,
    z.company_id,
    z.company_name,
    z.model_name,
    z.scenario_name,
    z.is_base,
    z.sort,
    z.sotp_year AS core_year,
    z.sotp_as_of AS as_of,
    z.core_pretax,
    z.core_earnings,
    z.r AS discount_rate,
    z.g AS terminal_growth,
    z.ronic,
    z.formula_multiple,
    z.multiple,
    z.core_value,
    z.segments_value,
    z.mature_value,
    z.mature_earnings,
    z.mature_multiple,
    z.growth_value,
    z.invest_value,
    z.direct_value,
    z.mature_earn_pv,
    z.mature_interim_pv,
    z.cash,
    z.debt,
    z.op_cash,
    z.repatriation,
    z.usable_net_cash,
    z.investments,
    z.minority_other,
    z.noncore,
    z.equity_value,
    z.shares,
    z.vps AS value_per_share,
    (z.vps / NULLIF(z.latest_fx, (0)::double precision)) AS value_per_share_quote,
    z.latest_price AS market_price,
    ((z.latest_price / NULLIF(z.vps, (0)::double precision)) - (1)::double precision) AS price_vs_value,
    (((z.mcap - z.noncore) - COALESCE(z.segments_value, (0)::double precision)) / NULLIF(z.core_earnings, (0)::double precision)) AS implied_core_multiple,
    z.implied_mature_multiple,
    z.implied_growth_value,
    z.probability,
    z.weighted_value,
    dv.value_today AS ddm_value,
    ((z.vps / NULLIF(dv.value_today, (0)::double precision)) - (1)::double precision) AS diff_vs_ddm,
    (z.vps * ((1)::double precision - z.margin_low)) AS watch_low,
    (z.vps * ((1)::double precision - z.margin_high)) AS watch_high,
    (
        CASE
            WHEN ((z.sotp_year IS NOT NULL) AND (z.core_earnings IS NULL)) THEN format('预测计算里没有 %s 年的数据，核心盈利无法计算'::text, z.sotp_year)
            WHEN ((z.sotp_year IS NOT NULL) AND (z.multiple IS NULL)) THEN '没有合理倍数：在情景里填“合理倍数”或“新增投资回报率”'::text
            WHEN (z.n_incomplete > 0) THEN format('经营分部有 %s 项输入不完整，无法计算（见「估值 / 经营分部估值」）'::text, z.n_incomplete)
            WHEN (z.n_segments = 0) THEN format('核心盈利 %s 亿元（%s 年）× 合理倍数 %s 倍 ＝ %s 亿元；可用净现金 %s 亿元；对外投资（折后）%s 亿元；少数股东权益与其他 %s 亿元；股权价值 %s 亿元，每股 %s 元%s。市场价 %s 元，%s；市场给核心业务的隐含倍数 %s 倍。股息贴现口径 %s 元。'::text, public.vi_fmt(z.core_earnings, 1), z.sotp_year, public.vi_fmt(z.multiple, 1), public.vi_fmt(z.core_value, 0), public.vi_fmt(z.usable_net_cash, 0), public.vi_fmt(z.investments, 0), public.vi_fmt(z.minority_other, 0), public.vi_fmt(z.equity_value, 0), public.vi_fmt(z.vps),
            CASE
                WHEN (z.latest_fx IS NOT NULL) THEN format('（约合股价币种 %s）'::text, public.vi_fmt((z.vps / z.latest_fx)))
                ELSE ''::text
            END, public.vi_fmt(z.latest_price),
            CASE
                WHEN (z.latest_price IS NULL) THEN '暂无市场价'::text
                WHEN (z.latest_price > z.vps) THEN format('高于每股价值 %s'::text, public.vi_pct(((z.latest_price / z.vps) - (1)::double precision)))
                ELSE format('低于每股价值 %s'::text, public.vi_pct(((1)::double precision - (z.latest_price / z.vps))))
            END, public.vi_fmt(((z.mcap - z.noncore) / NULLIF(z.core_earnings, (0)::double precision)), 1), public.vi_fmt(dv.value_today))
            ELSE format('%s经营分部合计 %s 亿元（成熟业务 %s、成长业务 %s、投入期业务 %s、直接估值业务 %s）；可用净现金 %s 亿元；对外投资（折后）%s 亿元；少数股东权益与其他 %s 亿元；股权价值 %s 亿元，每股 %s 元%s。市场价 %s 元，%s。%s%s%s股息贴现口径 %s 元。'::text,
            CASE
                WHEN (z.core_earnings IS NOT NULL) THEN format('核心盈利 %s 亿元（%s 年）× %s 倍 ＝ %s 亿元；'::text, public.vi_fmt(z.core_earnings, 1), z.sotp_year, public.vi_fmt(z.multiple, 1), public.vi_fmt(z.core_value, 0))
                ELSE ''::text
            END, public.vi_fmt(z.segments_value, 0), public.vi_fmt(COALESCE(z.mature_value, (0)::double precision), 0), public.vi_fmt(COALESCE(z.growth_value, (0)::double precision), 0), public.vi_fmt(COALESCE(z.invest_value, (0)::double precision), 0), public.vi_fmt(COALESCE(z.direct_value, (0)::double precision), 0), public.vi_fmt(z.usable_net_cash, 0), public.vi_fmt(z.investments, 0), public.vi_fmt(z.minority_other, 0), public.vi_fmt(z.equity_value, 0), public.vi_fmt(z.vps),
            CASE
                WHEN (z.latest_fx IS NOT NULL) THEN format('（约合股价币种 %s）'::text, public.vi_fmt((z.vps / z.latest_fx)))
                ELSE ''::text
            END, public.vi_fmt(z.latest_price),
            CASE
                WHEN (z.latest_price IS NULL) THEN '暂无市场价'::text
                WHEN (z.latest_price > z.vps) THEN format('高于每股价值 %s'::text, public.vi_pct(((z.latest_price / z.vps) - (1)::double precision)))
                ELSE format('低于每股价值 %s'::text, public.vi_pct(((1)::double precision - (z.latest_price / z.vps))))
            END,
            CASE
                WHEN (z.implied_mature_multiple IS NOT NULL) THEN format('其余部分按本模型取值时，市值对应成熟业务约 %s 倍正常化盈利（本模型 %s 倍）；'::text, public.vi_fmt(z.implied_mature_multiple, 1), public.vi_fmt(z.mature_multiple, 1))
                ELSE ''::text
            END,
            CASE
                WHEN (z.implied_growth_value IS NOT NULL) THEN format('或者说，市场为成长业务付了约 %s 亿元（本模型 %s 亿元）。'::text, public.vi_fmt(z.implied_growth_value, 0), public.vi_fmt(z.growth_value, 0))
                ELSE ''::text
            END,
            CASE
                WHEN (z.weighted_value IS NOT NULL) THEN format('按情景概率加权，每股 %s 元。'::text, public.vi_fmt(z.weighted_value))
                ELSE ''::text
            END, public.vi_fmt(dv.value_today))
        END || ' 研究提示，不是交易指令。'::text) AS conclusion
   FROM (z
     LEFT JOIN public.vi_valuation dv ON ((dv.id = z.scenario_id)));


ALTER VIEW public.vi_sotp OWNER TO nocobase;

--
-- Name: vi_thesis_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_thesis_calc AS
 SELECT t.id,
    x.latest_year AS check_latest_year,
    x.latest_value AS check_latest_value,
    x.result AS check_result,
    ( SELECT string_agg(((j.code || ' '::text) || COALESCE(j.status, '未定'::text)), '；'::text ORDER BY j.code) AS string_agg
           FROM (public.vi_lnk_judgment_theses l
             JOIN public.vi_judgment_base j ON ((j.id = l.judgment_id)))
          WHERE (l.thesis_id = t.id)) AS judgment_status
   FROM (public.vi_thesis_base t
     CROSS JOIN LATERAL public.vi_check_eval(t.company_id, t.check_metric, t.check_op, t.check_threshold, t.check_years) x(latest_year, latest_value, result));


ALTER VIEW public.vi_thesis_calc OWNER TO nocobase;

--
-- Name: vi_check; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_check AS
 WITH m AS (
         SELECT m.id,
            m.name AS model_name,
            m.company_id,
            co.name AS company_name,
            m.base_year AS b,
            m.terminal_year AS t,
            m.rf,
            mc.latest_rf,
            mc.latest_rf_date,
            mc.years_elapsed,
            cc.latest_price_date
           FROM (((public.vi_model_base m
             JOIN public.vi_model_calc mc ON ((mc.id = m.id)))
             LEFT JOIN public.vi_company_base co ON ((co.id = m.company_id)))
             LEFT JOIN public.vi_company_calc cc ON ((cc.id = m.company_id)))
          WHERE (m.status = '当前'::text)
        ), vb AS (
         SELECT vi_valuation.id,
            vi_valuation.model_id,
            vi_valuation.company_id,
            vi_valuation.company_name,
            vi_valuation.model_name,
            vi_valuation.scenario_name,
            vi_valuation.is_base,
            vi_valuation.sort,
            vi_valuation.discount_rate,
            vi_valuation.terminal_growth,
            vi_valuation.value_base_date,
            vi_valuation.value_today,
            vi_valuation.cash_value_today,
            vi_valuation.pv_explicit,
            vi_valuation.terminal_pv,
            vi_valuation.terminal_share,
            vi_valuation.market_price,
            vi_valuation.market_date,
            vi_valuation.price_vs_value,
            vi_valuation.watch_low,
            vi_valuation.watch_high,
            vi_valuation.years_complete,
            vi_valuation.cash_years,
            vi_valuation.required_return,
            vi_valuation.value_at_required,
            vi_valuation.implied_irr,
            vi_valuation.cash_implied_irr,
            vi_valuation.irr_spread,
            vi_valuation.conclusion
           FROM public.vi_valuation
          WHERE vi_valuation.is_base
        ), sb AS (
         SELECT vi_sotp.id,
            vi_sotp.model_id,
            vi_sotp.company_id,
            vi_sotp.company_name,
            vi_sotp.model_name,
            vi_sotp.scenario_name,
            vi_sotp.is_base,
            vi_sotp.sort,
            vi_sotp.core_year,
            vi_sotp.as_of,
            vi_sotp.core_pretax,
            vi_sotp.core_earnings,
            vi_sotp.discount_rate,
            vi_sotp.terminal_growth,
            vi_sotp.ronic,
            vi_sotp.formula_multiple,
            vi_sotp.multiple,
            vi_sotp.core_value,
            vi_sotp.segments_value,
            vi_sotp.mature_value,
            vi_sotp.mature_earnings,
            vi_sotp.mature_multiple,
            vi_sotp.growth_value,
            vi_sotp.invest_value,
            vi_sotp.direct_value,
            vi_sotp.mature_earn_pv,
            vi_sotp.mature_interim_pv,
            vi_sotp.cash,
            vi_sotp.debt,
            vi_sotp.op_cash,
            vi_sotp.repatriation,
            vi_sotp.usable_net_cash,
            vi_sotp.investments,
            vi_sotp.minority_other,
            vi_sotp.noncore,
            vi_sotp.equity_value,
            vi_sotp.shares,
            vi_sotp.value_per_share,
            vi_sotp.value_per_share_quote,
            vi_sotp.market_price,
            vi_sotp.price_vs_value,
            vi_sotp.implied_core_multiple,
            vi_sotp.implied_mature_multiple,
            vi_sotp.implied_growth_value,
            vi_sotp.probability,
            vi_sotp.weighted_value,
            vi_sotp.ddm_value,
            vi_sotp.diff_vs_ddm,
            vi_sotp.watch_low,
            vi_sotp.watch_high,
            vi_sotp.conclusion
           FROM public.vi_sotp
          WHERE vi_sotp.is_base
        ), c AS (
         SELECT m.id,
            m.model_name,
            m.company_id,
            m.company_name,
            m.b,
            m.t,
            m.rf,
            m.latest_rf,
            m.latest_rf_date,
            m.years_elapsed,
            m.latest_price_date,
            ( SELECT count(*) AS count
                   FROM public.vi_forecast_base f
                  WHERE ((f.model_id = m.id) AND ((f.year >= (m.b + 1)) AND (f.year <= m.t)))) AS n_fc,
            ( SELECT count(*) AS count
                   FROM (public.vi_forecast_base f
                     JOIN public.vi_forecast_calc fc USING (id))
                  WHERE ((f.model_id = m.id) AND fc.cash_complete)) AS n_cash,
            ( SELECT count(*) AS count
                   FROM public.vi_forecast_base f
                  WHERE ((f.model_id = m.id) AND (f.cash_status = '建议值待核验'::text))) AS n_cash_proposed,
            ( SELECT count(*) AS count
                   FROM public.vi_forecast_base f
                  WHERE ((f.model_id = m.id) AND (COALESCE(f.operating_status, ''::text) <> '已核验'::text))) AS n_op_unverified,
            ( SELECT string_agg(s.name, '、'::text) AS string_agg
                   FROM (public.vi_scenario_base s
                     JOIN public.vi_scenario_calc sc USING (id))
                  WHERE ((s.model_id = m.id) AND (sc.eff_discount_rate <= s.terminal_growth))) AS bad_rg,
            ( SELECT min(fc.debt_close) AS min
                   FROM (public.vi_forecast_base f
                     JOIN public.vi_forecast_calc fc USING (id))
                  WHERE (f.model_id = m.id)) AS min_debt,
            ( SELECT format('%s→%s'::text, public.vi_pct(min(f.cost_of_debt) FILTER (WHERE (f.year = (m.b + 1))), 2), public.vi_pct(min(f.cost_of_debt) FILTER (WHERE (f.year = m.t)), 2)) AS format
                   FROM public.vi_forecast_base f
                  WHERE (f.model_id = m.id)) AS cod_path,
            ( SELECT format('%s→%s 亿元'::text, public.vi_fmt(min(fc.debt_open) FILTER (WHERE (f.year = (m.b + 1))), 0), public.vi_fmt(min(fc.debt_close) FILTER (WHERE (f.year = m.t)), 0)) AS format
                   FROM (public.vi_forecast_base f
                     JOIN public.vi_forecast_calc fc USING (id))
                  WHERE (f.model_id = m.id)) AS debt_path,
            vb.terminal_share AS tv_share,
            ( SELECT count(*) AS count
                   FROM (public.vi_collector_base k
                     JOIN public.vi_collector_calc kc USING (id))
                  WHERE kc.needs_alert) AS n_alert,
            ( SELECT count(*) AS count
                   FROM ((public.vi_observation_base o
                     JOIN public.vi_observation_calc oc USING (id))
                     JOIN public.vi_metric_base mt ON ((mt.id = o.metric_id)))
                  WHERE ((NOT oc.is_valid) AND ((mt.company_id = m.company_id) OR (mt.company_id IS NULL)))) AS n_invalid,
            ( SELECT count(*) AS count
                   FROM (public.vi_thesis_base th
                     JOIN public.vi_thesis_calc tc USING (id))
                  WHERE ((th.company_id = m.company_id) AND (tc.check_result ~~ '已触发%'::text))) AS n_falsified,
            ( SELECT count(*) AS count
                   FROM (public.vi_thesis_base th
                     JOIN public.vi_thesis_calc tc USING (id))
                  WHERE ((th.company_id = m.company_id) AND (tc.check_result <> '未设置'::text))) AS n_checked,
            vb.implied_irr AS base_irr,
            vb.cash_implied_irr AS base_cash_irr,
            vb.value_at_required AS base_v_req,
            ( SELECT mb.required_return
                   FROM public.vi_model_base mb
                  WHERE (mb.id = m.id)) AS req,
            ( SELECT count(*) AS count
                   FROM public.vi_moat_base mo
                  WHERE (mo.company_id = m.company_id)) AS n_moat,
            ( SELECT format('真实壁垒 %s、局部优势 %s、伪壁垒 %s、待验证 %s'::text, count(*) FILTER (WHERE (mo.verdict = '真实壁垒'::text)), count(*) FILTER (WHERE (mo.verdict = '局部优势'::text)), count(*) FILTER (WHERE (mo.verdict = '伪壁垒'::text)), count(*) FILTER (WHERE ((mo.verdict IS NULL) OR (mo.verdict = '待验证'::text)))) AS format
                   FROM public.vi_moat_base mo
                  WHERE (mo.company_id = m.company_id)) AS moat_mix,
            ( SELECT count(*) AS count
                   FROM public.vi_moat_base mo
                  WHERE ((mo.company_id = m.company_id) AND (mo.verdict IS DISTINCT FROM '伪壁垒'::text) AND (NOT (EXISTS ( SELECT 1
                           FROM (public.vi_lnk_moat_theses l
                             JOIN public.vi_thesis_base t ON ((t.id = l.thesis_id)))
                          WHERE ((l.moat_id = mo.id) AND (t.debated_on IS NOT NULL))))))) AS n_moat_undebated,
            ( SELECT count(*) AS count
                   FROM (public.vi_moat_base mo
                     JOIN public.vi_moat_calc mc USING (id))
                  WHERE ((mo.company_id = m.company_id) AND (mc.check_result ~~ '已触发%'::text))) AS n_moat_broken,
            ( SELECT count(*) AS count
                   FROM public.vi_fit_score_base fs
                  WHERE ((fs.company_id = m.company_id) AND (fs.score IS NOT NULL))) AS n_fit,
            ( SELECT sum(fs.score) AS sum
                   FROM public.vi_fit_score_base fs
                  WHERE (fs.company_id = m.company_id)) AS fit_total,
            ( SELECT string_agg(z.txt, '；'::text ORDER BY z.sort) AS string_agg
                   FROM ( SELECT fs.sort,
                            format('%s %s 分，但 %s'::text, fs.dimension, fs.score, string_agg(((t.code || ' '::text) || t.status), '、'::text ORDER BY t.code)) AS txt
                           FROM ((public.vi_fit_score_base fs
                             JOIN public.vi_lnk_fit_score_theses l ON ((l.fit_score_id = fs.id)))
                             JOIN public.vi_thesis_base t ON ((t.id = l.thesis_id)))
                          WHERE ((fs.company_id = m.company_id) AND (fs.score >= 4) AND (t.status = ANY (ARRAY['存疑'::text, '证伪'::text])))
                          GROUP BY fs.id, fs.sort, fs.dimension, fs.score) z) AS fit_conflict,
            ( SELECT count(*) AS count
                   FROM public.vi_risk_base r
                  WHERE (r.company_id = m.company_id)) AS n_risk,
            ( SELECT format('重大 %s、重要 %s、一般 %s'::text, count(*) FILTER (WHERE (rc.level = '重大'::text)), count(*) FILTER (WHERE (rc.level = '重要'::text)), count(*) FILTER (WHERE (rc.level = '一般'::text))) AS format
                   FROM (public.vi_risk_base r
                     JOIN public.vi_risk_calc rc USING (id))
                  WHERE (r.company_id = m.company_id)) AS risk_mix,
            ( SELECT string_agg(r.code, '、'::text ORDER BY r.code) AS string_agg
                   FROM (public.vi_risk_base r
                     JOIN public.vi_risk_calc rc USING (id))
                  WHERE ((r.company_id = m.company_id) AND (rc.level = '重大'::text) AND (COALESCE(r.treatment, '未计入估值'::text) = '未计入估值'::text))) AS risk_unpriced,
            ( SELECT string_agg(r.code, '、'::text ORDER BY r.code) AS string_agg
                   FROM (public.vi_risk_base r
                     JOIN public.vi_risk_calc rc USING (id))
                  WHERE ((r.company_id = m.company_id) AND (rc.level = ANY (ARRAY['重大'::text, '重要'::text])) AND (NULLIF(TRIM(BOTH FROM r.early_warning), ''::text) IS NULL) AND (NOT (EXISTS ( SELECT 1
                           FROM public.vi_lnk_risk_watches l
                          WHERE (l.risk_id = r.id)))))) AS risk_no_signal,
            ( SELECT string_agg(r.code, '、'::text ORDER BY r.code) AS string_agg
                   FROM public.vi_risk_base r
                  WHERE ((r.company_id = m.company_id) AND ((r.probability IS NULL) OR (r.impact IS NULL) OR (r.treatment IS NULL)))) AS risk_incomplete,
            sb.value_per_share AS sotp_base,
            sb.diff_vs_ddm AS sotp_diff,
            sb.implied_core_multiple AS sotp_implied,
            sb.multiple AS sotp_multiple,
            vb.value_today AS ddm_base,
            ( SELECT count(*) AS count
                   FROM public.vi_sotp_segment_base g
                  WHERE (g.model_id = m.id)) AS n_seg,
            sb.mature_value AS seg_mature,
            sb.growth_value AS seg_growth,
            sb.invest_value AS seg_invest,
            sb.direct_value AS seg_direct,
            sb.noncore AS seg_noncore,
            sb.equity_value AS seg_equity,
            sb.implied_growth_value AS seg_implied_growth,
            sb.weighted_value AS seg_weighted,
            sb.mature_multiple AS seg_mature_mult,
            sb.implied_mature_multiple AS seg_implied_mature,
            ( SELECT sum(s.probability) AS sum
                   FROM public.vi_scenario_base s
                  WHERE (s.model_id = m.id)) AS prob_sum,
            ( SELECT count(s.probability) AS count
                   FROM public.vi_scenario_base s
                  WHERE (s.model_id = m.id)) AS prob_n
           FROM ((m
             LEFT JOIN vb ON ((vb.model_id = m.id)))
             LEFT JOIN sb ON ((sb.model_id = m.id)))
        )
 SELECT ((c.id * 100) + x.k) AS id,
    c.id AS model_id,
    c.company_id,
    c.company_name,
    c.model_name,
    x.code,
    x.name,
    x.result,
    x.detail
   FROM (c
     CROSS JOIN LATERAL ( VALUES (1,'C01'::text,'预测年份完整'::text,
                CASE
                    WHEN (c.n_fc = (c.t - c.b)) THEN '通过'::text
                    ELSE '阻断'::text
                END,format('需要 %s—%s 年共 %s 年逐年假设，现有 %s 年'::text, (c.b + 1), c.t, (c.t - c.b), c.n_fc)), (2,'C02'::text,'折现率大于永续增长率'::text,
                CASE
                    WHEN (c.bad_rg IS NULL) THEN '通过'::text
                    ELSE '阻断'::text
                END,COALESCE(('以下情景 r≤g：'::text || c.bad_rg), '所有情景 r>g'::text)), (3,'C03'::text,'现金桥接'::text,
                CASE
                    WHEN ((c.n_cash = (c.t - c.b)) AND (c.n_cash_proposed = 0)) THEN '通过'::text
                    WHEN (c.n_cash = (c.t - c.b)) THEN '提示'::text
                    ELSE '阻断'::text
                END,format('完整 %s / %s 年；其中 %s 年为建议值待核验'::text, c.n_cash, (c.t - c.b), c.n_cash_proposed)), (4,'C04'::text,'债务滚动'::text,
                CASE
                    WHEN (c.min_debt IS NULL) THEN '阻断'::text
                    WHEN (c.min_debt < (0)::double precision) THEN '阻断'::text
                    ELSE '通过'::text
                END,format('带息负债 %s；隐含平均债务成本 %s'::text, c.debt_path, c.cod_path)), (5,'C05'::text,'估值日与基准日'::text,
                CASE
                    WHEN (c.years_elapsed > 1.5) THEN '阻断'::text
                    WHEN (c.years_elapsed > 0.25) THEN '提示'::text
                    ELSE '通过'::text
                END,format('距基准日 %s 年。已按折现率把价值滚动到今天；若基准年之后的股息已在今天之前派发，需要从今天价值中扣除。基准日超过 1.5 年应更新模型。'::text, round(c.years_elapsed, 2))), (6,'C06'::text,'股价数据新鲜'::text,
                CASE
                    WHEN (c.latest_price_date IS NULL) THEN '阻断'::text
                    WHEN ((public.vi_today() - c.latest_price_date) > 7) THEN '提示'::text
                    ELSE '通过'::text
                END,format('最新股价日期 %s'::text, COALESCE((c.latest_price_date)::text, '无'::text))), (7,'C07'::text,'无风险利率参数与最新观察'::text,
                CASE
                    WHEN (c.latest_rf IS NULL) THEN '提示'::text
                    WHEN (abs(((c.latest_rf / (100)::double precision) - c.rf)) >= (0.005)::double precision) THEN '提示'::text
                    ELSE '通过'::text
                END,format('模型采用 %s；最新观察 %s（%s），相差 %s bp。长期参数不随单日数据自动修改。'::text, public.vi_pct(c.rf, 2),
                CASE
                    WHEN (c.latest_rf IS NULL) THEN '—'::text
                    ELSE ((c.latest_rf)::text || '%'::text)
                END, COALESCE((c.latest_rf_date)::text, '—'::text),
                CASE
                    WHEN (c.latest_rf IS NULL) THEN '—'::text
                    ELSE (round(((((c.latest_rf / (100)::double precision) - c.rf) * (10000)::double precision))::numeric))::text
                END)), (8,'C08'::text,'终值依赖度'::text,
                CASE
                    WHEN (c.tv_share > (0.7)::double precision) THEN '提示'::text
                    ELSE '通过'::text
                END,format('基准情景终值占比 %s（超过 70%% 时价值主要取决于远期假设）'::text, public.vi_pct(c.tv_share))), (9,'C09'::text,'论点证伪'::text,
                CASE
                    WHEN (c.n_falsified > 0) THEN '阻断'::text
                    ELSE '通过'::text
                END,format('%s 条论点设置了自动检查，%s 条已触发'::text, c.n_checked, c.n_falsified)), (10,'C10'::text,'经营假设核验'::text,
                CASE
                    WHEN (c.n_op_unverified > 0) THEN '提示'::text
                    ELSE '通过'::text
                END,format('%s 个年度的经营假设尚未标记为“已核验”'::text, c.n_op_unverified)), (11,'C11'::text,'自动采集健康'::text,
                CASE
                    WHEN (c.n_alert > 0) THEN '提示'::text
                    ELSE '通过'::text
                END,format('%s 个启用的采集源需要处理'::text, c.n_alert)), (12,'C12'::text,'无效高频数据'::text,
                CASE
                    WHEN (c.n_invalid > 0) THEN '提示'::text
                    ELSE '通过'::text
                END,format('%s 条观察超出指标合理范围（已排除在计算之外，原值保留）'::text, c.n_invalid)), (13,'C13'::text,'隐含收益率与要求收益率'::text,
                CASE
                    WHEN ((c.base_irr IS NULL) OR (c.req IS NULL)) THEN '提示'::text
                    WHEN (c.base_irr >= c.req) THEN '通过'::text
                    ELSE '提示'::text
                END,format('按最新市场价买入，基准情景隐含年化收益率 %s（现金支持口径 %s），要求收益率 %s；要求收益率下的最高买入价 %s 元。'::text, public.vi_pct(c.base_irr, 2), public.vi_pct(c.base_cash_irr, 2), public.vi_pct(c.req, 1), public.vi_fmt(c.base_v_req))), (14,'C14'::text,'竞争壁垒与辩论'::text,
                CASE
                    WHEN ((c.n_moat = 0) OR (c.n_moat_undebated > 0) OR (c.n_moat_broken > 0)) THEN '提示'::text
                    ELSE '通过'::text
                END,
                CASE
                    WHEN (c.n_moat = 0) THEN '还没有识别竞争壁垒（商业模式分析 / 竞争壁垒）'::text
                    ELSE format('%s 项候选壁垒（%s）；伪壁垒以外还有 %s 项没有关联辩论过的论点（核心论点里填辩论日期并关联壁垒）；壁垒自动检查已触发 %s 项'::text, c.n_moat, c.moat_mix, c.n_moat_undebated, c.n_moat_broken)
                END), (15,'C15'::text,'价值投资适配度'::text,
                CASE
                    WHEN ((c.n_fit < 8) OR (c.fit_total < 22)) THEN '提示'::text
                    ELSE '通过'::text
                END,format('已评 %s / 8 个维度，总分 %s / 40：%s'::text, c.n_fit, COALESCE(c.fit_total, (0)::bigint),
                CASE
                    WHEN (c.n_fit < 8) THEN '评分未完成'::text
                    WHEN (c.fit_total >= 32) THEN '适合价值投资复利框架（仍需价格安全边际）'::text
                    WHEN (c.fit_total >= 22) THEN '可研究，需说明更偏复利、现金流价值还是资产价值'::text
                    ELSE '通常不符合价值投资标准'::text
                END)), (16,'C16'::text,'分部加总与股息贴现对照'::text,
                CASE
                    WHEN (c.sotp_base IS NULL) THEN '通过'::text
                    WHEN (abs(c.sotp_diff) > (0.25)::double precision) THEN '提示'::text
                    ELSE '通过'::text
                END,
                CASE
                    WHEN (c.sotp_base IS NULL) THEN '未设置分部加总，只用股息贴现'::text
                    WHEN ((c.sotp_implied IS NULL) AND (c.seg_mature_mult IS NOT NULL)) THEN format('基准情景：分部加总 %s 元，股息贴现 %s 元，相差 %s（超过 25%% 时要说明差异来源，常见是股息贴现没有计入留存的现金与对外投资）；成熟业务倍数 %s 倍，市场隐含成熟业务倍数 %s 倍'::text, public.vi_fmt(c.sotp_base), public.vi_fmt(c.ddm_base), public.vi_pct(c.sotp_diff), public.vi_fmt(c.seg_mature_mult, 1), public.vi_fmt(c.seg_implied_mature, 1))
                    ELSE format('基准情景：分部加总 %s 元，股息贴现 %s 元，相差 %s（超过 25%% 时要说明差异来源，常见是股息贴现没有计入留存的现金与对外投资）；合理倍数 %s 倍，市场隐含核心倍数 %s 倍'::text, public.vi_fmt(c.sotp_base), public.vi_fmt(c.ddm_base), public.vi_pct(c.sotp_diff), public.vi_fmt(c.sotp_multiple, 1), public.vi_fmt(c.sotp_implied, 1))
                END), (17,'C17'::text,'经营分部估值'::text,
                CASE
                    WHEN (c.n_seg = 0) THEN '通过'::text
                    WHEN (c.sotp_base IS NULL) THEN '阻断'::text
                    WHEN (((c.prob_n > 0) AND (abs((c.prob_sum - (1)::double precision)) > (0.005)::double precision)) OR ((c.seg_growth / NULLIF(c.seg_equity, (0)::double precision)) > (0.4)::double precision)) THEN '提示'::text
                    ELSE '通过'::text
                END,
                CASE
                    WHEN (c.n_seg = 0) THEN '未使用经营分部估值'::text
                    WHEN (c.sotp_base IS NULL) THEN '经营分部或分部估值项输入不完整，基准情景算不出每股价值（见「估值 / 经营分部估值」）'::text
                    ELSE format('基准情景：成熟业务 %s 亿元、成长业务 %s 亿元、投入期业务 %s 亿元、直接估值业务 %s 亿元、非经营部分 %s 亿元；成长业务占股权价值 %s（超过 40%% 时提示：价值主要取决于尚未成熟的业务）。市场隐含成长业务价值 %s 亿元。情景概率合计 %s（应为 100%%），概率加权每股 %s 元。'::text, public.vi_fmt(c.seg_mature, 0), public.vi_fmt(c.seg_growth, 0), public.vi_fmt(c.seg_invest, 0), public.vi_fmt(c.seg_direct, 0), public.vi_fmt(c.seg_noncore, 0), public.vi_pct((c.seg_growth / NULLIF(c.seg_equity, (0)::double precision))), public.vi_fmt(c.seg_implied_growth, 0),
                    CASE
                        WHEN (c.prob_n = 0) THEN '未填'::text
                        ELSE public.vi_pct(c.prob_sum)
                    END, public.vi_fmt(c.seg_weighted))
                END), (18,'C18'::text,'适配度与论点一致'::text,
                CASE
                    WHEN (c.fit_conflict IS NULL) THEN '通过'::text
                    ELSE '提示'::text
                END,COALESCE((('给了 4 分以上、但关联论点是存疑或证伪的维度：'::text || c.fit_conflict) || '。要么下调评分，要么说明为什么论点存疑不影响这个维度'::text), '4 分以上的维度，关联论点都不是存疑或证伪'::text)), (19,'C19'::text,'风险分析'::text,
                CASE
                    WHEN ((c.n_risk = 0) OR (c.risk_unpriced IS NOT NULL) OR (c.risk_no_signal IS NOT NULL) OR (c.risk_incomplete IS NOT NULL)) THEN '提示'::text
                    ELSE '通过'::text
                END,
                CASE
                    WHEN (c.n_risk = 0) THEN '还没有做风险分析（商业模式 / 风险分析）'::text
                    ELSE ((((format('%s 条风险（%s）'::text, c.n_risk, c.risk_mix) || COALESCE((('；重大风险未计入估值：'::text || c.risk_unpriced) || '（在悲观情景或参数里体现，或在影响测算里说明为什么不计）'::text), ''::text)) || COALESCE(('；重大、重要风险缺预警信号：'::text || c.risk_no_signal), ''::text)) || COALESCE(('；可能性、冲击或估值处理没填：'::text || c.risk_incomplete), ''::text)) ||
                    CASE
                        WHEN ((c.risk_unpriced IS NULL) AND (c.risk_no_signal IS NULL) AND (c.risk_incomplete IS NULL)) THEN '；重大风险都已计入估值，重大、重要风险都有预警信号'::text
                        ELSE ''::text
                    END)
                END)) x(k, code, name, result, detail));


ALTER VIEW public.vi_check OWNER TO nocobase;

--
-- Name: vi_collect_run_base; Type: TABLE; Schema: public; Owner: nocobase
--

CREATE TABLE public.vi_collect_run_base (
    id bigint NOT NULL,
    label text,
    trigger_source text,
    status text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    company_id bigint
);


ALTER TABLE public.vi_collect_run_base OWNER TO nocobase;

--
-- Name: TABLE vi_collect_run_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_collect_run_base IS '采集运行：每次手动触发采集的记录和结果；被【原始采集记录】引用。每按一次“立即采集”新增一行，触发“④ 手动采集”工作流跑完 采集→入库→自检；有公司时只采这家公司和通用指标，结果按本次的原始记录自动统计。';


--
-- Name: COLUMN vi_collect_run_base.label; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_collect_run_base.label IS '运行：例如：手动｜2026-10-21 23:50';


