--
-- Name: TABLE vi_fin_history_base; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON TABLE public.vi_fin_history_base IS '历史年度：财务模型的历史一侧：每年的关键财务和经营数字，和逐年假设同一套列；引用【来源文档】；被【竞争壁垒】【核心论点】引用。一年一行，是财务模型的历史实际（逐年假设是预测）。报表项按当年年报披露口径录入，与「财务数据」自动对账（tools/fin_stmt.py check），重组追溯等口径差写在口径说明；业务量、分红、每股股息、带息负债、折旧摊销等报表外或需定口径的项目只录在这里。空白＝尚未取得，不是 0。派生指标（单价、派息率、同比、ROE 等）自动计算，论点与竞争壁垒的自动检查读这里。';


--
-- Name: COLUMN vi_fin_history_base.year; Type: COMMENT; Schema: public; Owner: nocobase
--

COMMENT ON COLUMN public.vi_fin_history_base.year IS '年度';


--
