--
-- Name: vi_fin_metric; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_fin_metric AS
 SELECT h.company_id,
    h.year,
    x.metric,
    x.value
   FROM ((public.vi_fin_history_base h
     JOIN public.vi_fin_history_calc c USING (id))
     CROSS JOIN LATERAL ( VALUES ('业务量'::text,h.volume), ('单价'::text,c.price), ('营业收入'::text,h.revenue), ('归母净利润'::text,h.np_parent), ('派息率'::text,c.payout), ('财务费用'::text,h.finance_cost), ('业务量同比'::text,c.volume_yoy), ('单价同比'::text,c.price_yoy), ('营业收入同比'::text,c.revenue_yoy), ('财务费用同比'::text,c.finance_cost_yoy), ('毛利率'::text,c.gross_margin), ('ROE'::text,c.roe), ('经营现金流÷归母净利润'::text,c.cfo_to_np), ('资本开支÷经营现金流'::text,c.capex_to_cfo), ('净负债'::text,c.net_debt), ('净负债÷EBITDA'::text,c.net_debt_to_ebitda)) x(metric, value))
  WHERE (x.value IS NOT NULL);


ALTER VIEW public.vi_fin_metric OWNER TO nocobase;

