--
-- Name: vi_metric_calc; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_metric_calc AS
 SELECT m.id,
    (( SELECT count(*) AS count
           FROM public.vi_observation_base o
          WHERE (o.metric_id = m.id)))::integer AS obs_count,
    l.value AS latest_value,
    l.obs_date AS latest_date,
        CASE
            WHEN (m.company_id IS NULL) THEN '宏观'::text
            ELSE '公司'::text
        END AS scope,
    u.used_by,
    u.used_by_codes
   FROM ((public.vi_metric_base m
     LEFT JOIN LATERAL ( SELECT x.value,
            x.obs_date
           FROM public.vi_obs_current x
          WHERE (x.metric_id = m.id)
          ORDER BY x.obs_date DESC
         LIMIT 1) l ON (true))
     LEFT JOIN LATERAL ( SELECT string_agg((((c.name || '（'::text) || cm.usages) || '）'::text), '；'::text ORDER BY c.id) AS used_by,
            ((','::text || string_agg(c.code, ','::text ORDER BY c.id)) || ','::text) AS used_by_codes
           FROM (public.vi_company_metric cm
             JOIN public.vi_company_base c ON ((c.id = cm.company_id)))
          WHERE (cm.metric_id = m.id)) u ON (true));


ALTER VIEW public.vi_metric_calc OWNER TO nocobase;

