--
-- Name: vi_sensitivity; Type: VIEW; Schema: public; Owner: nocobase
--

CREATE VIEW public.vi_sensitivity AS
 WITH base AS (
         SELECT v_1.model_id,
            v_1.id AS scenario_id,
            v_1.discount_rate AS r0,
            v_1.terminal_growth AS g0,
            v_1.company_id,
            v_1.company_name,
            v_1.model_name,
            m.base_year AS b,
            m.terminal_year AS t,
            m.shares,
            mc.years_elapsed
           FROM ((public.vi_valuation v_1
             JOIN public.vi_model_base m ON ((m.id = v_1.model_id)))
             JOIN public.vi_model_calc mc ON ((mc.id = m.id)))
          WHERE (v_1.is_base AND v_1.years_complete)
        ), grid AS (
         SELECT base.model_id,
            base.scenario_id,
            base.r0,
            base.g0,
            base.company_id,
            base.company_name,
            base.model_name,
            base.b,
            base.t,
            base.shares,
            base.years_elapsed,
            i.i,
            j.j,
            (((i.i - 3))::numeric * 0.005) AS dr,
            (((j.j - 3))::numeric * 0.005) AS dg
           FROM base,
            generate_series(1, 5) i(i),
            generate_series(1, 5) j(j)
        ), val AS (
         SELECT grid.model_id,
            grid.scenario_id,
            grid.r0,
            grid.g0,
            grid.company_id,
            grid.company_name,
            grid.model_name,
            grid.b,
            grid.t,
            grid.shares,
            grid.years_elapsed,
            grid.i,
            grid.j,
            grid.dr,
            grid.dg,
            (grid.r0 + (grid.dr)::double precision) AS r,
            (grid.g0 + (grid.dg)::double precision) AS g,
            ( SELECT sum((p.dividend / power((((1)::double precision + grid.r0) + (grid.dr)::double precision), ((p.year - grid.b))::double precision))) AS sum
                   FROM public.vi_projection p
                  WHERE ((p.scenario_id = grid.scenario_id) AND ((p.year >= (grid.b + 1)) AND (p.year <= grid.t)))) AS pv,
            ( SELECT p.dividend
                   FROM public.vi_projection p
                  WHERE ((p.scenario_id = grid.scenario_id) AND (p.year = grid.t))) AS td
           FROM grid
        ), v AS (
         SELECT val.model_id,
            val.scenario_id,
            val.r0,
            val.g0,
            val.company_id,
            val.company_name,
            val.model_name,
            val.b,
            val.t,
            val.shares,
            val.years_elapsed,
            val.i,
            val.j,
            val.dr,
            val.dg,
            val.r,
            val.g,
            val.pv,
            val.td,
                CASE
                    WHEN ((val.r > val.g) AND (val.shares > (0)::double precision)) THEN ((val.pv + (((val.td * ((1)::double precision + val.g)) / (val.r - val.g)) / power(((1)::double precision + val.r), ((val.t - val.b))::double precision))) / val.shares)
                    ELSE NULL::double precision
                END AS v0
           FROM val
        )
 SELECT (((model_id * 1000) + (i * 10)) + j) AS id,
    model_id,
    company_id,
    company_name,
    model_name,
    format('r%s / g%s'::text, (
        CASE
            WHEN (dr >= (0)::numeric) THEN '+'::text
            ELSE ''::text
        END || public.vi_pct((dr)::double precision, 1)), (
        CASE
            WHEN (dg >= (0)::numeric) THEN '+'::text
            ELSE ''::text
        END || public.vi_pct((dg)::double precision, 1))) AS label,
    dr AS r_shift,
    dg AS g_shift,
    r,
    g,
    v0 AS value_base_date,
    (v0 * power(((1)::double precision + r), (years_elapsed)::double precision)) AS value_today
   FROM v;


ALTER VIEW public.vi_sensitivity OWNER TO nocobase;

