    v.multiple_used,
    v.r AS eff_rate,
    v.tau AS years_to_value,
    v.terminal_pv,
    v.interim_pv,
    v.value,
    COALESCE(s.name, '全部情景'::text) AS scope
   FROM ((public.vi_sotp_segment_base g
     LEFT JOIN public.vi_scenario_base s ON ((s.id = g.scenario_id)))
     LEFT JOIN LATERAL ( SELECT v_1.id,
            v_1.scenario_id,
            v_1.model_id,
            v_1.scenario_name,
            v_1.is_base,
            v_1.segment_id,
            v_1.code,
            v_1.name,
            v_1.method,
            v_1.earn_year,
            v_1.revenue,
            v_1.op_margin,
            v_1.tax_rate,
            v_1.attrib,
            v_1.r,
            v_1.growth,
            v_1.ronic,
            v_1.earnings,
            v_1.formula_multiple,
            v_1.multiple_used,
            v_1.tau,
            v_1.interim_cash,
            v_1.commit_amount,
            v_1.commit_years,
            v_1.ongoing_cost,
            v_1.direct_value,
            v_1.terminal_pv,
            v_1.interim_pv,
            v_1.earn_pv,
            v_1.value
           FROM public.vi_sotp_segment_val v_1
          WHERE (v_1.segment_id = g.id)
          ORDER BY v_1.is_base DESC, v_1.scenario_id
         LIMIT 1) v ON (true));


